/**
 * Softglass — shared engine (all languages)
 * Only colors / surface recipes change per theme.
 * Radius, spacing, type scale, glass structure stay shared.
 */

:root {
  /* —— Radius (soft, never sharp) —— */
  --sg-radius-xs: 0.75rem; /* 12px */
  --sg-radius-sm: 1rem; /* 16px */
  --sg-radius-md: 1.25rem; /* 20px */
  --sg-radius-lg: 1.5rem; /* 24px */
  --sg-radius-xl: 2rem; /* 32px */
  --sg-radius-pill: 999px;

  /* —— Spacing scale —— */
  --sg-space-0: 0;
  --sg-space-1: 0.25rem;
  --sg-space-2: 0.5rem;
  --sg-space-3: 0.75rem;
  --sg-space-4: 1rem;
  --sg-space-5: 1.25rem;
  --sg-space-6: 1.5rem;
  --sg-space-8: 2rem;
  --sg-space-10: 2.5rem;
  --sg-space-12: 3rem;
  --sg-space-16: 4rem;

  /* —— Type scale (fluid-friendly) —— */
  --sg-font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  --sg-font-display: var(--sg-font-sans);
  --sg-text-xs: 0.75rem;
  --sg-text-sm: 0.875rem;
  --sg-text-base: 1rem;
  --sg-text-lg: 1.125rem;
  --sg-text-xl: 1.25rem;
  --sg-text-2xl: 1.5rem;
  --sg-text-3xl: clamp(1.75rem, 1.4rem + 1.2vw, 2.25rem);
  --sg-text-4xl: clamp(2rem, 1.5rem + 2vw, 3rem);
  --sg-leading-tight: 1.25;
  --sg-leading-normal: 1.55;
  --sg-leading-relaxed: 1.7;
  --sg-tracking-tight: -0.02em;
  --sg-tracking-normal: 0;
  --sg-font-weight-normal: 400;
  --sg-font-weight-medium: 500;
  --sg-font-weight-semibold: 600;
  --sg-font-weight-bold: 700;

  /* —— Motion —— */
  --sg-ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --sg-duration-fast: 150ms;
  --sg-duration-normal: 220ms;
  --sg-duration-slow: 360ms;

  /* —— Glass structure defaults (themes override values) —— */
  --sg-glass-blur: 16px;
  --sg-glass-blur-mobile: 10px;
  --sg-glass-saturate: 1.35;
  --sg-border-width: 1px;

  /* Frost defaults — themes override for readable chrome */
  --sg-surface-frost: rgba(255, 255, 255, 0.9);
  --sg-surface-frost-strong: rgba(255, 255, 255, 0.96);
  --sg-border-frost: rgba(15, 23, 42, 0.12);

  /* —— Z-index —— */
  --sg-z-base: 0;
  --sg-z-raised: 10;
  --sg-z-dropdown: 40;
  --sg-z-sticky: 50;
  /* Overlays sit well above sticky chrome (header/sidebar) */
  --sg-z-modal: 1000;
  --sg-z-toast: 1100;

  /* Toast stack: tight elevation so shadows do not bleed into the gap */
  --sg-shadow-toast: 0 4px 14px rgba(15, 23, 42, 0.1),
    0 1px 3px rgba(15, 23, 42, 0.06);

  /* —— Touch / layout —— */
  --sg-touch-min: 2.75rem; /* 44px */
  --sg-content-max: 72rem;
  --sg-sidebar-width: 16rem;

  color-scheme: light;
}

/* Reduced transparency → solid fallbacks (accessibility) */
@media (prefers-reduced-transparency: reduce) {
  :root {
    --sg-glass-blur: 0px;
    --sg-glass-blur-mobile: 0px;
    --sg-surface-glass: var(--sg-surface-solid);
    --sg-surface-glass-elevated: var(--sg-surface-solid);
    --sg-surface-frost: var(--sg-surface-solid);
    --sg-surface-frost-strong: var(--sg-surface-solid);
  }
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --sg-duration-fast: 0ms;
    --sg-duration-normal: 0ms;
    --sg-duration-slow: 0ms;
  }
}

/* Shared material utilities — language-agnostic structure */
.sg-surface-solid {
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  border-radius: var(--sg-radius-md);
  box-shadow: var(--sg-shadow-soft);
}

/* Cards/chrome: prefer frost (opaque + cheap). True blur only when .sg-blur is set. */
.sg-surface-glass {
  background: var(--sg-surface-frost);
  color: var(--sg-fg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  border-radius: var(--sg-radius-lg);
  box-shadow: var(--sg-shadow-glass);
  background-image: linear-gradient(
    180deg,
    var(--sg-gloss-highlight) 0%,
    transparent 42%
  );
}

.sg-surface-glass-elevated {
  background: var(--sg-surface-frost-strong);
  color: var(--sg-fg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  border-radius: var(--sg-radius-lg);
  box-shadow: var(--sg-shadow-elevated);
  background-image: linear-gradient(
    180deg,
    var(--sg-gloss-highlight) 0%,
    transparent 48%
  );
}

.sg-surface-glass.sg-blur,
.sg-surface-glass-elevated.sg-blur {
  backdrop-filter: blur(var(--sg-glass-blur)) saturate(var(--sg-glass-saturate));
  -webkit-backdrop-filter: blur(var(--sg-glass-blur))
    saturate(var(--sg-glass-saturate));
  background: var(--sg-surface-glass);
}

.sg-surface-glass-elevated.sg-blur {
  background: var(--sg-surface-glass-elevated);
}

.sg-badge-sm {
  padding: 0.15rem 0.45rem;
  font-size: 0.65rem;
}

.sg-badge-lg {
  padding: 0.35rem 0.85rem;
  font-size: var(--sg-text-sm);
}

.sg-badge-dot::before {
  content: "";
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.85;
}

.sg-field-required::after {
  content: " *";
  color: var(--sg-danger);
}

.sg-input-block {
  width: 100%;
}

.sg-input-group {
  display: flex;
  align-items: stretch;
  width: 100%;
  border-radius: var(--sg-radius-sm);
  overflow: hidden;
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-solid);
}

.sg-input-group:focus-within {
  border-color: var(--sg-accent);
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-input-group .sg-input {
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.sg-input-group .sg-input:focus {
  box-shadow: none;
}

.sg-input-addon {
  display: inline-flex;
  align-items: center;
  padding: 0 0.75rem;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg-muted);
  background: var(--sg-accent-soft);
  white-space: nowrap;
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .sg-surface-glass,
  .sg-surface-glass-elevated {
    background: var(--sg-surface-solid);
    background-image: none;
  }
}

@media (max-width: 767px) {
  .sg-surface-glass.sg-blur,
  .sg-surface-glass-elevated.sg-blur {
    backdrop-filter: blur(var(--sg-glass-blur-mobile))
      saturate(var(--sg-glass-saturate));
    -webkit-backdrop-filter: blur(var(--sg-glass-blur-mobile))
      saturate(var(--sg-glass-saturate));
  }
}

/* —— Button —— */
.sg-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sg-space-2);
  min-height: var(--sg-touch-min);
  padding: 0.625rem 1.25rem;
  border-radius: var(--sg-radius-pill);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  border: var(--sg-border-width) solid transparent;
  cursor: pointer;
  text-decoration: none;
  user-select: none;
  transition: transform var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out),
    background var(--sg-duration-fast) var(--sg-ease-out),
    opacity var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-btn:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-btn:active:not(:disabled) {
  transform: translateY(1px);
}

.sg-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sg-btn-sm {
  min-height: 2.25rem;
  padding: 0.4rem 0.9rem;
  font-size: var(--sg-text-xs);
}

.sg-btn-lg {
  min-height: 3rem;
  padding: 0.75rem 1.5rem;
  font-size: var(--sg-text-base);
}

.sg-btn-icon {
  width: var(--sg-touch-min);
  padding-inline: 0;
}

.sg-btn-sm.sg-btn-icon {
  width: 2.25rem;
}

.sg-btn-lg.sg-btn-icon {
  width: 3rem;
}

.sg-btn-primary {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  box-shadow: var(--sg-shadow-soft), inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-btn-primary:hover:not(:disabled) {
  background: var(--sg-accent-hover);
}

.sg-btn-secondary {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  border-color: var(--sg-border-subtle);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-btn-secondary:hover:not(:disabled) {
  background: var(--sg-surface-glass-elevated);
}

.sg-btn-ghost {
  background: var(--sg-surface-frost);
  color: var(--sg-fg);
  border-color: var(--sg-border-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-btn-ghost:hover:not(:disabled) {
  background: var(--sg-surface-frost-strong);
}

.sg-btn-outline {
  background: transparent;
  color: var(--sg-fg);
  border-color: var(--sg-border-subtle);
}

.sg-btn-outline:hover:not(:disabled) {
  background: var(--sg-accent-soft);
  border-color: var(--sg-accent);
}

.sg-btn-danger {
  background: var(--sg-danger);
  color: #fff;
  box-shadow: var(--sg-shadow-soft), inset 0 1px 0 rgba(255, 255, 255, 0.25);
}

.sg-btn-danger:hover:not(:disabled) {
  filter: brightness(1.05);
}

.sg-btn-link {
  background: transparent;
  color: var(--sg-accent);
  border-color: transparent;
  box-shadow: none;
  min-height: auto;
  padding-inline: 0.25rem;
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

.sg-btn-link:hover:not(:disabled) {
  color: var(--sg-accent-hover);
}

.sg-btn-block {
  width: 100%;
}

.sg-btn-rounded-soft {
  border-radius: var(--sg-radius-sm);
}

.sg-btn-rounded-md {
  border-radius: var(--sg-radius-md);
}

.sg-btn-loading {
  position: relative;
  color: transparent !important;
  pointer-events: none;
}

.sg-btn-loading > * {
  opacity: 0;
}

.sg-btn-spinner {
  position: absolute;
  inset: 0;
  margin: auto;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, currentColor 25%, transparent);
  border-top-color: var(--sg-accent-fg);
  opacity: 1 !important;
  animation: sg-spin 0.7s linear infinite;
}

.sg-btn-ghost .sg-btn-spinner,
.sg-btn-outline .sg-btn-spinner,
.sg-btn-secondary .sg-btn-spinner,
.sg-btn-link .sg-btn-spinner {
  border-top-color: var(--sg-fg);
}

.sg-btn-icon-slot {
  display: inline-flex;
  flex-shrink: 0;
  width: 1.1em;
  height: 1.1em;
  align-items: center;
  justify-content: center;
}

.sg-btn-icon-slot svg {
  width: 1.1em;
  height: 1.1em;
}

@keyframes sg-spin {
  to {
    transform: rotate(360deg);
  }
}

/* —— Input / Field —— */
.sg-field {
  display: grid;
  gap: var(--sg-space-2);
}

.sg-field-label {
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  color: var(--sg-fg);
}

.sg-field-hint {
  font-size: var(--sg-text-xs);
  color: var(--sg-fg-subtle);
}

.sg-field-error {
  font-size: var(--sg-text-xs);
  color: var(--sg-danger);
}

.sg-input {
  width: 100%;
  min-height: var(--sg-touch-min);
  padding: 0.625rem 1rem;
  border-radius: var(--sg-radius-sm);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-base);
  transition: border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-input::placeholder {
  color: var(--sg-fg-muted);
}

.sg-input:focus {
  outline: none;
  border-color: var(--sg-accent);
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-input:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.sg-input[aria-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-input-sm {
  min-height: 2.25rem;
  padding: 0.4rem 0.75rem;
  font-size: var(--sg-text-sm);
}

.sg-input-lg {
  min-height: 3rem;
  padding: 0.75rem 1.1rem;
  font-size: var(--sg-text-lg);
}

/* —— Textarea —— */
.sg-textarea {
  width: 100%;
  min-height: 6.5rem;
  padding: 0.75rem 1rem;
  border-radius: var(--sg-radius-sm);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-base);
  line-height: var(--sg-leading-normal);
  resize: vertical;
  transition: border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-textarea::placeholder {
  color: var(--sg-fg-muted);
}

.sg-textarea:focus {
  outline: none;
  border-color: var(--sg-accent);
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-textarea:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  resize: none;
}

.sg-textarea[aria-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-textarea-sm {
  min-height: 4.5rem;
  padding: 0.5rem 0.75rem;
  font-size: var(--sg-text-sm);
}

.sg-textarea-lg {
  min-height: 9rem;
  padding: 0.9rem 1.1rem;
  font-size: var(--sg-text-lg);
}

.sg-textarea-auto {
  resize: none;
  field-sizing: content;
  min-height: 3.5rem;
}

/* —— Checkbox / Radio —— */
.sg-check-root {
  display: inline-flex;
  align-items: flex-start;
  gap: var(--sg-space-3);
  cursor: pointer;
  user-select: none;
  max-width: 100%;
}

.sg-check-root[data-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
}

.sg-check-control {
  position: relative;
  flex-shrink: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.15rem;
  border-radius: 0.4rem;
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-check-control[data-kind="radio"] {
  border-radius: var(--sg-radius-pill);
}

.sg-check-input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  width: 100%;
  height: 100%;
  cursor: inherit;
}

.sg-check-input:focus-visible + .sg-check-face {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-check-face {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  display: grid;
  place-items: center;
  pointer-events: none;
}

.sg-check-control[data-checked="true"] {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
}

.sg-check-control[data-checked="true"][data-kind="radio"] .sg-check-dot {
  opacity: 1;
  transform: scale(1);
}

.sg-check-mark {
  width: 0.7rem;
  height: 0.7rem;
  opacity: 0;
  transform: scale(0.6);
  transition: opacity var(--sg-duration-fast) var(--sg-ease-out),
    transform var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-check-control[data-checked="true"] .sg-check-mark {
  opacity: 1;
  transform: scale(1);
}

.sg-check-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--sg-accent-fg);
  opacity: 0;
  transform: scale(0.5);
  transition: opacity var(--sg-duration-fast) var(--sg-ease-out),
    transform var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-check-label {
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  color: var(--sg-fg);
  line-height: 1.4;
}

.sg-check-hint {
  display: block;
  margin-top: 0.15rem;
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-normal);
  color: var(--sg-fg-muted);
}

.sg-check-group {
  display: grid;
  gap: var(--sg-space-3);
}

.sg-check-group-label {
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  color: var(--sg-fg);
  margin: 0 0 var(--sg-space-1);
}

/* —— Tooltip —— */
.sg-tooltip-wrap {
  position: relative;
  display: inline-flex;
  max-width: 100%;
}

.sg-tooltip {
  position: absolute;
  z-index: var(--sg-z-dropdown);
  left: 50%;
  bottom: calc(100% + 0.45rem);
  transform: translateX(-50%);
  min-width: max-content;
  max-width: min(16rem, 70vw);
  padding: 0.4rem 0.65rem;
  border-radius: var(--sg-radius-sm);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost-strong);
  color: var(--sg-fg);
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1.4;
  box-shadow: var(--sg-shadow-elevated);
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--sg-duration-fast) var(--sg-ease-out),
    visibility var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-tooltip[data-placement="bottom"] {
  bottom: auto;
  top: calc(100% + 0.45rem);
}

.sg-tooltip[data-open="true"] {
  opacity: 1;
  visibility: visible;
}

.sg-tooltip-arrow {
  position: absolute;
  left: 50%;
  top: 100%;
  width: 0.45rem;
  height: 0.45rem;
  background: var(--sg-surface-frost-strong);
  border-right: var(--sg-border-width) solid var(--sg-border-frost);
  border-bottom: var(--sg-border-width) solid var(--sg-border-frost);
  transform: translateX(-50%) translateY(-55%) rotate(45deg);
}

.sg-tooltip[data-placement="bottom"] .sg-tooltip-arrow {
  top: auto;
  bottom: 100%;
  transform: translateX(-50%) translateY(55%) rotate(45deg);
}

/* —— Badge —— */
.sg-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.625rem;
  border-radius: var(--sg-radius-pill);
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1.2;
  background: var(--sg-surface-glass);
  color: var(--sg-fg-muted);
  border: var(--sg-border-width) solid var(--sg-border-glass);
}

.sg-badge-accent {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  border-color: color-mix(in srgb, var(--sg-accent) 25%, transparent);
}

.sg-badge-solid {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
}

.sg-badge-success {
  background: color-mix(in srgb, var(--sg-success) 14%, transparent);
  color: var(--sg-success);
  border-color: color-mix(in srgb, var(--sg-success) 28%, transparent);
}

.sg-badge-warning {
  background: color-mix(in srgb, var(--sg-warning) 14%, transparent);
  color: var(--sg-warning);
  border-color: color-mix(in srgb, var(--sg-warning) 28%, transparent);
}

.sg-badge-danger {
  background: color-mix(in srgb, var(--sg-danger) 14%, transparent);
  color: var(--sg-danger);
  border-color: color-mix(in srgb, var(--sg-danger) 28%, transparent);
}

/* —— Card —— */
.sg-card {
  display: flex;
  flex-direction: column;
  gap: var(--sg-space-4);
  padding: var(--sg-space-5);
  border-radius: var(--sg-radius-lg);
  color: var(--sg-fg);
  /* Avoid layout containment — it traps absolute select/menus under next cards */
  overflow: visible;
}

.sg-card-sm {
  padding: var(--sg-space-3);
  gap: var(--sg-space-3);
}

.sg-card-lg {
  padding: var(--sg-space-8);
  gap: var(--sg-space-5);
}

.sg-card-flush {
  padding: 0;
}

.sg-card-hoverable {
  transition: transform var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-card-hoverable:hover {
  transform: translateY(-2px);
  box-shadow: var(--sg-shadow-elevated);
}

.sg-card-clickable {
  cursor: pointer;
}

.sg-card-header {
  display: flex;
  flex-direction: column;
  gap: var(--sg-space-1);
}

.sg-card-title {
  margin: 0;
  font-size: var(--sg-text-lg);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  line-height: var(--sg-leading-tight);
}

.sg-card-description {
  margin: 0;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg-muted);
  line-height: var(--sg-leading-normal);
}

.sg-card-content {
  flex: 1;
  min-width: 0;
}

.sg-card-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--sg-space-3);
  margin-top: auto;
}

/* —— App shell —— */
.sg-app-bg {
  min-height: 100dvh;
  background-color: var(--sg-bg);
  background-image: var(--sg-bg-image);
  /* fixed attachment forces full-viewport repaints — scroll jank */
  background-attachment: scroll;
  background-repeat: no-repeat;
  background-size: cover;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  line-height: var(--sg-leading-normal);
}

.sg-shell {
  display: grid;
  min-height: 100dvh;
  grid-template-columns: 1fr;
  grid-template-rows: auto 1fr;
  grid-template-areas:
    "header"
    "main";
}

.sg-shell-with-sidebar {
  grid-template-columns: var(--sg-sidebar-width) 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar main";
}

.sg-shell-header {
  grid-area: header;
  position: sticky;
  top: 0;
  z-index: var(--sg-z-sticky);
  padding: var(--sg-space-3) var(--sg-space-4);
}

.sg-shell-header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  padding: 0.75rem 1rem;
  max-width: var(--sg-content-max);
  margin-inline: auto;
  width: 100%;
}

.sg-shell-with-sidebar .sg-shell-header-inner {
  max-width: none;
  margin-inline: 0;
}

.sg-shell-sidebar {
  grid-area: sidebar;
  display: none;
  flex-direction: column;
  gap: var(--sg-space-4);
  padding: var(--sg-space-5);
  border-right: var(--sg-border-width) solid var(--sg-border-glass);
  position: sticky;
  top: 0;
  height: 100dvh;
  overflow: auto;
}

.sg-shell-main {
  grid-area: main;
  width: 100%;
  min-width: 0;
}

.sg-shell-main-inner {
  max-width: var(--sg-content-max);
  margin-inline: auto;
  padding: var(--sg-space-5) var(--sg-space-4) var(--sg-space-12);
  width: 100%;
}

.sg-shell-with-sidebar .sg-shell-main-inner {
  max-width: none;
}

.sg-shell-nav {
  display: flex;
  flex-direction: column;
  gap: var(--sg-space-1);
}

.sg-shell-nav-item {
  display: flex;
  align-items: center;
  gap: var(--sg-space-2);
  min-height: 2.5rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--sg-radius-sm);
  color: var(--sg-fg-muted);
  text-decoration: none;
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  border: var(--sg-border-width) solid transparent;
  transition: background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-shell-nav-item:hover {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
}

.sg-shell-nav-item[data-active="true"] {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  border-color: color-mix(in srgb, var(--sg-accent) 20%, transparent);
}

.sg-blob {
  position: absolute;
  border-radius: 50%;
  /* No filter:blur — soft radial is enough and far cheaper */
  filter: none;
  opacity: var(--sg-blob-opacity, 0.35);
  pointer-events: none;
  z-index: var(--sg-z-base);
  background: radial-gradient(
    circle,
    var(--sg-blob-color, var(--sg-accent)) 0%,
    transparent 70%
  );
}

/* —— Avatar —— */
.sg-avatar {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
  border-radius: var(--sg-radius-pill);
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  user-select: none;
  border: var(--sg-border-width) solid var(--sg-border-glass);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-avatar-sm {
  width: 2rem;
  height: 2rem;
  font-size: var(--sg-text-xs);
}

.sg-avatar-md {
  width: 2.5rem;
  height: 2.5rem;
  font-size: var(--sg-text-sm);
}

.sg-avatar-lg {
  width: 3.25rem;
  height: 3.25rem;
  font-size: var(--sg-text-base);
}

.sg-avatar-xl {
  width: 4rem;
  height: 4rem;
  font-size: var(--sg-text-lg);
}

.sg-avatar-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.sg-avatar-fallback {
  line-height: 1;
}

.sg-avatar-group {
  display: inline-flex;
  align-items: center;
}

.sg-avatar-group .sg-avatar {
  margin-left: -0.45rem;
  box-shadow: 0 0 0 2px var(--sg-bg), inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-avatar-group .sg-avatar:first-child {
  margin-left: 0;
}

/* —— Switch —— */
.sg-switch-root {
  display: inline-flex;
  align-items: center;
  gap: var(--sg-space-3);
  cursor: pointer;
  user-select: none;
}

.sg-switch-root[data-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
}

.sg-switch {
  position: relative;
  width: 2.75rem;
  height: 1.6rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-glass);
  background: var(--sg-surface-glass);
  backdrop-filter: blur(var(--sg-glass-blur-mobile));
  -webkit-backdrop-filter: blur(var(--sg-glass-blur-mobile));
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  transition: background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
  flex-shrink: 0;
  padding: 0;
  cursor: inherit;
}

.sg-switch:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-switch[data-checked="true"] {
  background: var(--sg-accent);
  border-color: transparent;
}

.sg-switch-thumb {
  position: absolute;
  top: 50%;
  left: 0.15rem;
  width: 1.2rem;
  height: 1.2rem;
  border-radius: var(--sg-radius-pill);
  background: #fff;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
  transform: translate(0, -50%);
  transition: transform var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-switch[data-checked="true"] .sg-switch-thumb {
  transform: translate(1.1rem, -50%);
}

.sg-switch-label {
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  color: var(--sg-fg);
}

.sg-switch-hint {
  display: block;
  margin-top: 0.15rem;
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-normal);
  color: var(--sg-fg-muted);
}

/* —— Tabs —— */
.sg-tabs {
  display: flex;
  flex-direction: column;
  gap: var(--sg-space-4);
  width: 100%;
}

.sg-tabs-list {
  display: inline-flex;
  flex-wrap: wrap;
  gap: var(--sg-space-1);
  padding: var(--sg-space-1);
  border-radius: var(--sg-radius-pill);
  width: fit-content;
  max-width: 100%;
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight), var(--sg-shadow-soft);
  backdrop-filter: blur(var(--sg-glass-blur)) saturate(var(--sg-glass-saturate));
  -webkit-backdrop-filter: blur(var(--sg-glass-blur))
    saturate(var(--sg-glass-saturate));
}

.sg-tabs-trigger {
  appearance: none;
  border: var(--sg-border-width) solid transparent;
  background: transparent;
  color: var(--sg-fg-muted);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  letter-spacing: var(--sg-tracking-tight);
  min-height: 2.25rem;
  padding: 0.4rem 0.9rem;
  border-radius: var(--sg-radius-pill);
  cursor: pointer;
  transition: background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

/* Hover only for inactive tabs - active keeps solid accent */
.sg-tabs-trigger:hover:not(:disabled):not([data-active="true"]) {
  color: var(--sg-fg);
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 14%, transparent);
}

.sg-tabs-trigger:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-tabs-trigger:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sg-tabs-trigger[data-active="true"] {
  color: var(--sg-accent-fg);
  background: var(--sg-accent);
  border-color: transparent;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  font-weight: var(--sg-font-weight-semibold);
}

.sg-tabs-trigger[data-active="true"]:hover:not(:disabled) {
  color: var(--sg-accent-fg);
  background: var(--sg-accent-hover);
  border-color: transparent;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-tabs-content {
  min-width: 0;
  outline: none;
}

.sg-tabs-content[hidden] {
  display: none;
}

/* —— Select (custom glass dropdown — matches Button language) —— */
.sg-select-root {
  position: relative;
  width: 100%;
}

/*
 * Open menus must stack above following sibling cards (card paint order).
 * Without this, absolute menus render under the next .sg-card in the page.
 */
.sg-select-root:has([data-open="true"]),
.sg-select-root:has([aria-expanded="true"]),
.sg-combobox-root:has([aria-expanded="true"]),
.sg-multiselect-root:has([data-open="true"]),
.sg-datepicker-root:has([data-open="true"]),
.sg-datepicker-root:has([aria-expanded="true"]) {
  z-index: calc(var(--sg-z-dropdown) + 20);
  isolation: isolate;
}

.sg-select-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  width: 100%;
  min-height: var(--sg-touch-min);
  padding: 0.625rem 0.9rem 0.625rem 1.15rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  /* Frosted - readable, not see-through */
  background: var(--sg-surface-frost);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  line-height: 1.2;
  cursor: pointer;
  text-align: left;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight), var(--sg-shadow-soft);
  backdrop-filter: blur(18px) saturate(var(--sg-glass-saturate));
  -webkit-backdrop-filter: blur(18px) saturate(var(--sg-glass-saturate));
  transition: background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out),
    transform var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-select-trigger:hover:not(:disabled) {
  background: var(--sg-surface-frost-strong);
  border-color: color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-frost));
}

.sg-select-trigger:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-select-trigger:active:not(:disabled) {
  transform: translateY(1px);
}

.sg-select-trigger:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sg-select-trigger[data-open="true"] {
  background: var(--sg-surface-frost-strong);
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-frost));
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight), 0 0 0 3px var(--sg-ring-soft);
}

.sg-select-trigger[aria-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight),
    0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-select-trigger-sm {
  min-height: 2.25rem;
  padding: 0.4rem 0.75rem 0.4rem 0.9rem;
  font-size: var(--sg-text-xs);
}

.sg-select-trigger-lg {
  min-height: 3rem;
  padding: 0.75rem 1rem 0.75rem 1.35rem;
  font-size: var(--sg-text-base);
}

.sg-select-value {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sg-select-value[data-placeholder="true"] {
  color: var(--sg-fg-muted);
  font-weight: var(--sg-font-weight-medium);
}

.sg-select-chevron {
  flex-shrink: 0;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: var(--sg-radius-pill);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  transition: transform var(--sg-duration-fast) var(--sg-ease-out),
    background var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-select-trigger[data-open="true"] .sg-select-chevron {
  transform: rotate(180deg);
  background: color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

.sg-select-chevron svg {
  width: 0.85rem;
  height: 0.85rem;
  display: block;
}

.sg-select-menu {
  position: absolute;
  z-index: var(--sg-z-dropdown);
  top: calc(100% + 0.4rem);
  left: 0;
  right: 0;
  margin: 0;
  padding: var(--sg-space-2);
  list-style: none;
  max-height: min(16rem, 50dvh);
  overflow: auto;
  border-radius: var(--sg-radius-lg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  /* Strong frost so options stay readable on busy backgrounds */
  background-color: var(--sg-surface-frost-strong);
  background-image: linear-gradient(
    180deg,
    var(--sg-gloss-highlight) 0%,
    transparent 36%
  );
  box-shadow: var(--sg-shadow-elevated);
  backdrop-filter: blur(22px) saturate(1.35);
  -webkit-backdrop-filter: blur(22px) saturate(1.35);
  animation: sg-select-in var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-select-menu[data-placement="top"] {
  top: auto;
  bottom: calc(100% + 0.4rem);
  animation-name: sg-select-in-top;
}

/* Portaled panels (v1.2d): fixed coords from JS — ignore absolute anchors */
.sg-select-menu[data-portaled],
.sg-popover-content[data-portaled],
.sg-menu-content[data-portaled] {
  position: fixed;
  right: auto;
  bottom: auto;
  /* top/left/width come from inline style */
  translate: none;
  z-index: calc(var(--sg-z-dropdown) + 40);
}

.sg-select-menu[data-portaled] {
  /* matchWidth sets width; drop stretch-to-parent */
  left: auto;
  right: auto;
}

.sg-select-menu[data-portaled][data-placement="top"],
.sg-popover-content[data-portaled][data-placement="top"],
.sg-menu-content[data-portaled][data-placement="top"] {
  top: auto; /* still overridden by inline top */
  bottom: auto;
  animation-name: sg-select-in-top;
}

.sg-select-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  width: 100%;
  min-height: 2.5rem;
  padding: 0.5rem 0.85rem;
  border: var(--sg-border-width) solid transparent;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  letter-spacing: var(--sg-tracking-tight);
  text-align: left;
  cursor: pointer;
  transition: background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

/* Highlight only when not selected — avoids muddy mix on active row */
.sg-select-option:hover:not(:disabled):not([data-selected="true"]),
.sg-select-option[data-highlighted="true"]:not([data-selected="true"]) {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 18%, transparent);
  color: var(--sg-fg);
}

.sg-select-option[data-selected="true"] {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  font-weight: var(--sg-font-weight-semibold);
}

.sg-select-option[data-selected="true"][data-highlighted="true"],
.sg-select-option[data-selected="true"]:hover:not(:disabled) {
  background: var(--sg-accent-hover);
  color: var(--sg-accent-fg);
  filter: none;
}

.sg-select-option:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sg-select-option:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-select-check {
  flex-shrink: 0;
  width: 1rem;
  height: 1rem;
  opacity: 0;
}

.sg-select-option[data-selected="true"] .sg-select-check {
  opacity: 1;
}

/* —— DatePicker (v1.2b) — solid trigger + frost month panel —— */
.sg-datepicker-root {
  position: relative;
  width: 100%;
}

.sg-datepicker-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  width: 100%;
  min-height: var(--sg-touch-min);
  padding: 0.625rem 0.9rem 0.625rem 1.15rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  /* Solid field for typing contrast — calendar chrome stays frost */
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  line-height: 1.2;
  cursor: pointer;
  text-align: left;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight), var(--sg-shadow-soft);
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-datepicker-trigger:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--sg-accent) 28%, var(--sg-border-subtle));
}

.sg-datepicker-trigger:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-datepicker-trigger:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sg-datepicker-trigger[data-open="true"] {
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-subtle));
  box-shadow:
    inset 0 1px 0 var(--sg-gloss-highlight),
    0 0 0 3px var(--sg-ring-soft);
}

.sg-datepicker-trigger[aria-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow:
    inset 0 1px 0 var(--sg-gloss-highlight),
    0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-datepicker-trigger-sm {
  min-height: 2.25rem;
  padding: 0.4rem 0.75rem 0.4rem 0.9rem;
  font-size: var(--sg-text-xs);
}

.sg-datepicker-trigger-lg {
  min-height: 3rem;
  padding: 0.75rem 1rem 0.75rem 1.35rem;
  font-size: var(--sg-text-base);
}

.sg-datepicker-value {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sg-datepicker-value[data-placeholder="true"] {
  color: var(--sg-fg-muted);
  font-weight: var(--sg-font-weight-medium);
}

.sg-datepicker-icon {
  flex-shrink: 0;
  width: 1.35rem;
  height: 1.35rem;
  border-radius: var(--sg-radius-pill);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
}

.sg-datepicker-icon svg {
  width: 0.9rem;
  height: 0.9rem;
  display: block;
}

.sg-datepicker-panel {
  position: absolute;
  z-index: var(--sg-z-dropdown);
  top: calc(100% + 0.4rem);
  left: 0;
  width: min(19.5rem, 100vw - 1.5rem);
  margin: 0;
  padding: var(--sg-space-3);
  border-radius: var(--sg-radius-lg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background-color: var(--sg-surface-frost-strong);
  background-image: linear-gradient(
    180deg,
    var(--sg-gloss-highlight) 0%,
    transparent 36%
  );
  box-shadow: var(--sg-shadow-elevated);
  backdrop-filter: blur(22px) saturate(1.35);
  -webkit-backdrop-filter: blur(22px) saturate(1.35);
  color: var(--sg-fg);
  animation: sg-select-in var(--sg-duration-fast) var(--sg-ease-out);
  box-sizing: border-box;
}

.sg-datepicker-panel[data-placement="top"] {
  top: auto;
  bottom: calc(100% + 0.4rem);
  animation-name: sg-select-in-top;
}

/* Body portal — fixed coords from useFloatingPortal (Select language) */
.sg-datepicker-panel[data-portaled] {
  position: fixed;
  top: auto;
  left: auto;
  bottom: auto;
  right: auto;
  margin: 0;
}

.sg-datepicker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-2);
  margin-bottom: var(--sg-space-3);
}

.sg-datepicker-caption {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  min-width: 0;
}

.sg-datepicker-caption-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2rem;
  padding: 0.25rem 0.55rem;
  border: var(--sg-border-width) solid transparent;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-datepicker-caption-btn:hover {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 18%, transparent);
}

.sg-datepicker-caption-btn:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-datepicker-caption-btn-wide {
  flex: 1;
}

/* Month / year choice grid (same frost language as day cells) */
.sg-datepicker-picker-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.35rem;
  min-height: 12.5rem;
}

.sg-datepicker-picker-cell {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.5rem;
  padding: 0.35rem 0.4rem;
  border: var(--sg-border-width) solid transparent;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-datepicker-picker-cell:hover:not(:disabled):not([data-selected="true"]) {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 18%, transparent);
}

.sg-datepicker-picker-cell[data-today="true"]:not([data-selected="true"]) {
  border-color: color-mix(in srgb, var(--sg-accent) 45%, transparent);
  font-weight: var(--sg-font-weight-semibold);
}

.sg-datepicker-picker-cell[data-selected="true"] {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  font-weight: var(--sg-font-weight-semibold);
}

.sg-datepicker-picker-cell[data-selected="true"]:hover:not(:disabled) {
  background: var(--sg-accent-hover);
  color: var(--sg-accent-fg);
}

.sg-datepicker-picker-cell:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.sg-datepicker-picker-cell:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-datepicker-nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  border: var(--sg-border-width) solid transparent;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg);
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-datepicker-nav:hover {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 18%, transparent);
}

.sg-datepicker-nav:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-datepicker-nav svg {
  width: 1rem;
  height: 1rem;
  display: block;
}

.sg-datepicker-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.15rem;
  margin-bottom: 0.25rem;
}

.sg-datepicker-weekday {
  text-align: center;
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--sg-fg-muted);
  padding: 0.2rem 0;
}

.sg-datepicker-grid {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.sg-datepicker-row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.15rem;
}

.sg-datepicker-day {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.15rem;
  width: 100%;
  padding: 0;
  border: var(--sg-border-width) solid transparent;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-datepicker-day:hover:not(:disabled):not([data-selected="true"]) {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 18%, transparent);
}

.sg-datepicker-day[data-outside="true"] {
  color: var(--sg-fg-muted);
  opacity: 0.55;
}

.sg-datepicker-day[data-today="true"]:not([data-selected="true"]) {
  border-color: color-mix(in srgb, var(--sg-accent) 45%, transparent);
  font-weight: var(--sg-font-weight-semibold);
}

.sg-datepicker-day[data-selected="true"] {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  font-weight: var(--sg-font-weight-semibold);
  opacity: 1;
}

.sg-datepicker-day[data-selected="true"]:hover:not(:disabled) {
  background: var(--sg-accent-hover);
  color: var(--sg-accent-fg);
}

.sg-datepicker-day:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.sg-datepicker-day:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-select-check svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* —— Combobox / MultiSelect (v1.1 Sprint D) —— */
.sg-combobox-trigger {
  cursor: text;
  gap: var(--sg-space-2);
}

.sg-combobox-input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
  padding: 0;
  margin: 0;
  width: 100%;
}

.sg-combobox-input::placeholder {
  color: var(--sg-fg-muted);
  opacity: 1;
}

.sg-combobox-input:disabled {
  cursor: not-allowed;
}

.sg-combobox-empty {
  padding: 0.65rem 0.85rem;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg-muted);
  list-style: none;
}

.sg-multiselect-trigger {
  height: auto;
  min-height: var(--sg-touch-min);
  /* Center placeholder + chips with caret (flex-start left "Pick tags" too high) */
  align-items: center;
  padding-top: 0.4rem;
  padding-bottom: 0.4rem;
  cursor: pointer;
}

.sg-multiselect-trigger[data-disabled="true"] {
  opacity: 0.45;
  cursor: not-allowed;
  pointer-events: none;
}

.sg-multiselect-caret {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 0.2rem;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  border-radius: var(--sg-radius-pill);
}

.sg-multiselect-caret:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-multiselect-caret:disabled {
  cursor: not-allowed;
}

.sg-multiselect-chips {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  gap: 0.35rem;
  align-items: center;
  min-width: 0;
  min-height: 1.75rem;
  text-align: left;
}

/* Empty-state placeholder — sit on the same optical line as normal select text */
.sg-multiselect-chips .sg-select-value[data-placeholder="true"] {
  display: flex;
  align-items: center;
  min-height: 1.75rem;
  line-height: 1.35;
  padding: 0;
}

.sg-multiselect-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  max-width: 100%;
  /* Extra right padding so X hit area fits comfortably */
  padding: 0.2rem 0.15rem 0.2rem 0.6rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid
    color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-frost));
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1.2;
}

.sg-multiselect-chip-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding-right: 0.1rem;
}

.sg-multiselect-chip-x {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* Visible control ~28px — easy finger/mouse target */
  min-width: 1.75rem;
  min-height: 1.75rem;
  width: 1.75rem;
  height: 1.75rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: color-mix(in srgb, var(--sg-fg) 6%, transparent);
  cursor: pointer;
  color: var(--sg-fg-muted);
  line-height: 1;
  font-size: 1.05rem;
  font-family: inherit;
  flex-shrink: 0;
}

/* Invisible expanded hit box beyond the visible circle */
.sg-multiselect-chip-x::before {
  content: "";
  position: absolute;
  inset: -0.2rem;
  border-radius: 999px;
}

.sg-multiselect-chip-x:hover:not(:disabled) {
  color: var(--sg-fg);
  background: color-mix(in srgb, var(--sg-fg) 12%, transparent);
}

.sg-multiselect-chip-x:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-multiselect-trigger .sg-select-chevron {
  margin-top: 0;
  flex-shrink: 0;
}

@keyframes sg-select-in {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes sg-select-in-top {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* —— Popover + DropdownMenu (overlay family, v1.1 Sprint A) —— */
.sg-popover-root,
.sg-menu-root {
  position: relative;
  display: inline-flex;
  vertical-align: middle;
}

/* —— ContextMenu target (panel rules live after .sg-menu-content) —— */
/* Avoid display:contents — fixed menu + focus are more reliable with a real box. */
.sg-context-root {
  display: block;
}

.sg-context-target {
  display: block;
  outline: none;
}

.sg-context-target:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
  border-radius: var(--sg-radius-md);
}

.sg-popover-trigger {
  display: inline-flex;
}

.sg-menu-trigger-fallback {
  display: inline-flex;
  align-items: center;
  gap: var(--sg-space-2);
  min-height: 2.5rem;
  padding: 0 1rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  cursor: pointer;
}

.sg-menu-trigger-fallback:hover:not(:disabled) {
  background: var(--sg-surface-frost-strong);
}

.sg-menu-trigger-fallback:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sg-popover-content,
.sg-menu-content {
  position: absolute;
  z-index: var(--sg-z-dropdown);
  min-width: 12rem;
  max-width: min(20rem, 90vw);
  margin: 0;
  padding: var(--sg-space-2);
  border-radius: var(--sg-radius-lg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background-color: var(--sg-surface-frost-strong);
  background-image: linear-gradient(
    180deg,
    var(--sg-gloss-highlight) 0%,
    transparent 36%
  );
  box-shadow: var(--sg-shadow-elevated);
  backdrop-filter: blur(22px) saturate(1.35);
  -webkit-backdrop-filter: blur(22px) saturate(1.35);
  color: var(--sg-fg);
  animation: sg-select-in var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-popover-content {
  padding: var(--sg-space-4);
  min-width: 14rem;
}

.sg-popover-content[data-placement="bottom"],
.sg-menu-content[data-placement="bottom"] {
  top: calc(100% + 0.4rem);
  bottom: auto;
}

.sg-popover-content[data-placement="top"],
.sg-menu-content[data-placement="top"] {
  top: auto;
  bottom: calc(100% + 0.4rem);
  animation-name: sg-select-in-top;
}

.sg-popover-content[data-align="start"],
.sg-menu-content[data-align="start"] {
  left: 0;
  right: auto;
}

.sg-popover-content[data-align="center"],
.sg-menu-content[data-align="center"] {
  left: 50%;
  right: auto;
  /* `translate` is independent of enter animation `transform` */
  translate: -50% 0;
}

.sg-popover-content[data-align="end"],
.sg-menu-content[data-align="end"] {
  left: auto;
  right: 0;
}

.sg-menu-content {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  max-height: min(18rem, 50dvh);
  overflow: auto;
  min-width: 11rem;
}

/* ContextMenu: fixed at pointer — must beat .sg-menu-content absolute rules */
.sg-menu-content.sg-context-menu-content {
  position: fixed;
  top: auto;
  bottom: auto;
  right: auto;
  translate: none;
  z-index: var(--sg-z-dropdown);
}

.sg-menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  width: 100%;
  min-height: 2.35rem;
  padding: 0.45rem 0.85rem;
  border: var(--sg-border-width) solid transparent;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  letter-spacing: var(--sg-tracking-tight);
  text-align: left;
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-menu-item:hover:not(:disabled),
.sg-menu-item[data-highlighted="true"]:not(:disabled) {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 18%, transparent);
}

.sg-menu-item[data-destructive="true"] {
  color: var(--sg-danger, #e11d48);
}

.sg-menu-item[data-destructive="true"]:hover:not(:disabled),
.sg-menu-item[data-destructive="true"][data-highlighted="true"]:not(:disabled) {
  background: color-mix(in srgb, var(--sg-danger, #e11d48) 14%, transparent);
  border-color: color-mix(in srgb, var(--sg-danger, #e11d48) 22%, transparent);
  color: var(--sg-danger, #e11d48);
}

.sg-menu-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sg-menu-item:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 1px;
}

.sg-menu-item-label {
  flex: 1;
  min-width: 0;
}

.sg-menu-item-shortcut {
  flex-shrink: 0;
  font-size: var(--sg-text-xs);
  color: var(--sg-fg-muted);
  font-weight: var(--sg-font-weight-medium);
  letter-spacing: 0.02em;
}

.sg-menu-separator {
  height: 1px;
  margin: 0.3rem 0.4rem;
  background: var(--sg-border-frost);
  border: 0;
}

.sg-menu-label {
  padding: 0.4rem 0.85rem 0.25rem;
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--sg-fg-muted);
}

/* —— Modal —— */
/* Portaled to body: always viewport-centered, above sticky header */
.sg-modal-root {
  position: fixed;
  inset: 0;
  z-index: var(--sg-z-modal);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--sg-space-4);
  isolation: isolate;
  box-sizing: border-box;
  /* Prefer dynamic viewport so mobile browser chrome does not shift center */
  width: 100vw;
  min-height: 100vh;
  min-height: 100dvh;
}

.sg-modal-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  padding: 0;
  margin: 0;
  cursor: pointer;
  background: color-mix(in srgb, var(--sg-bg) 35%, rgba(15, 23, 42, 0.45));
  backdrop-filter: blur(8px) saturate(1.1);
  -webkit-backdrop-filter: blur(8px) saturate(1.1);
  animation: sg-fade-in var(--sg-duration-normal) var(--sg-ease-out);
}

.sg-modal-panel {
  position: relative;
  z-index: 1;
  width: min(100%, 28rem);
  max-height: min(90dvh, 40rem);
  overflow: auto;
  padding: var(--sg-space-6);
  display: flex;
  flex-direction: column;
  gap: var(--sg-space-4);
  margin: 0;
  flex-shrink: 0;
  /* enter animation: motion-recipes.css via data-motion */
}

.sg-modal-panel-lg {
  width: min(100%, 36rem);
}

.sg-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sg-space-3);
}

.sg-modal-title {
  margin: 0;
  font-size: var(--sg-text-xl);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  line-height: var(--sg-leading-tight);
}

.sg-modal-description {
  margin: 0.35rem 0 0;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg-muted);
  line-height: var(--sg-leading-normal);
}

.sg-modal-body {
  min-width: 0;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg);
}

.sg-modal-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--sg-space-3);
  margin-top: var(--sg-space-2);
}

.sg-modal-close {
  flex-shrink: 0;
}

/* —— Toast —— */
.sg-toast-viewport {
  position: fixed;
  z-index: var(--sg-z-toast);
  display: flex;
  flex-direction: column;
  /* Clear air between cards so soft shadows do not look like one smudge */
  gap: var(--sg-space-3);
  width: min(100% - 2rem, 24rem);
  max-height: calc(100dvh - 2 * var(--sg-space-4));
  overflow: auto;
  overscroll-behavior: contain;
  padding: 0;
  margin: 0;
  list-style: none;
  pointer-events: none;
  isolation: isolate;
}

.sg-toast-viewport-top-right {
  top: var(--sg-space-4);
  right: var(--sg-space-4);
  flex-direction: column;
}

/* Newest toast sits closest to the corner (stack grows upward) */
.sg-toast-viewport-bottom-right,
.sg-toast-viewport-bottom-center {
  flex-direction: column-reverse;
}

.sg-toast-viewport-bottom-right {
  bottom: var(--sg-space-4);
  right: var(--sg-space-4);
}

.sg-toast-viewport-bottom-center {
  bottom: var(--sg-space-4);
  left: 50%;
  transform: translateX(-50%);
}

/* Dedicated toast surface — elevated glass shadow is too soft/wide for stacks */
.sg-surface-frost-toast {
  background: var(--sg-surface-frost-strong);
  color: var(--sg-fg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  border-radius: var(--sg-radius-lg);
  box-shadow: var(--sg-shadow-toast);
  background-image: linear-gradient(
    180deg,
    var(--sg-gloss-highlight) 0%,
    transparent 48%
  );
}

.sg-toast {
  pointer-events: auto;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: var(--sg-space-2) var(--sg-space-3);
  align-items: start;
  padding: var(--sg-space-4);
  width: 100%;
  /* Own stacking context so sibling shadows do not composite into a dirty band */
  isolation: isolate;
  position: relative;
  /* enter: motion-recipes.css via data-motion */
}

/* leave recipes live in motion-recipes.css (data-leaving + data-motion) */

.sg-toast-title {
  margin: 0;
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
}

.sg-toast-description {
  margin: 0.2rem 0 0;
  font-size: var(--sg-text-xs);
  color: var(--sg-fg-muted);
  line-height: var(--sg-leading-normal);
  grid-column: 1;
}

.sg-toast-close {
  grid-column: 2;
  grid-row: 1;
}

.sg-toast-success {
  border-color: color-mix(in srgb, var(--sg-success) 35%, var(--sg-border-glass));
}

.sg-toast-warning {
  border-color: color-mix(in srgb, var(--sg-warning) 35%, var(--sg-border-glass));
}

.sg-toast-danger {
  border-color: color-mix(in srgb, var(--sg-danger) 35%, var(--sg-border-glass));
}

@keyframes sg-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes sg-scale-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes sg-toast-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sg-toast-out {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .sg-modal-backdrop,
  .sg-modal-panel,
  .sg-toast,
  .sg-toast[data-leaving="true"],
  .sg-select-menu,
  .sg-select-menu[data-placement="top"] {
    animation: none;
  }
}

@media (min-width: 900px) {
  .sg-shell-with-sidebar {
    grid-template-rows: auto 1fr;
  }

  .sg-shell-with-sidebar .sg-shell-sidebar {
    display: flex;
  }
}

@media (max-width: 899px) {
  .sg-shell-with-sidebar {
    grid-template-columns: 1fr;
    grid-template-areas:
      "header"
      "main";
  }
}


/* —— Spinner (standalone) —— */
.sg-spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--sg-accent);
}

.sg-spinner-visual {
  display: block;
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, currentColor 22%, transparent);
  border-top-color: currentColor;
  animation: sg-spin 0.7s linear infinite;
}

.sg-spinner-sm .sg-spinner-visual {
  width: 0.9rem;
  height: 0.9rem;
  border-width: 1.5px;
}

.sg-spinner-lg .sg-spinner-visual {
  width: 1.75rem;
  height: 1.75rem;
  border-width: 2.5px;
}

/* —— Separator —— */
.sg-separator {
  display: block;
  width: 100%;
  height: 1px;
  border: 0;
  margin: var(--sg-space-4) 0;
  background: linear-gradient(
    90deg,
    transparent,
    var(--sg-border-subtle) 12%,
    var(--sg-border-subtle) 88%,
    transparent
  );
  flex-shrink: 0;
}

.sg-separator-vertical {
  display: inline-block;
  width: 1px;
  height: 1.25rem;
  margin: 0 var(--sg-space-3);
  align-self: center;
  background: linear-gradient(
    180deg,
    transparent,
    var(--sg-border-subtle) 12%,
    var(--sg-border-subtle) 88%,
    transparent
  );
}

/* —— Skeleton —— */
.sg-skeleton {
  display: block;
  width: 100%;
  height: 0.875rem;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--sg-fg-muted) 10%, var(--sg-surface-solid)) 0%,
    color-mix(in srgb, var(--sg-fg-muted) 18%, var(--sg-surface-solid)) 45%,
    color-mix(in srgb, var(--sg-fg-muted) 10%, var(--sg-surface-solid)) 100%
  );
  background-size: 200% 100%;
  animation: sg-skeleton-shimmer 1.4s ease-in-out infinite;
}

.sg-skeleton-circle {
  border-radius: 50%;
  width: 2.5rem;
  height: 2.5rem;
}

.sg-skeleton-rounded-sm {
  border-radius: var(--sg-radius-xs);
}

.sg-skeleton-rounded-md {
  border-radius: var(--sg-radius-sm);
}

.sg-skeleton-rounded-lg {
  border-radius: var(--sg-radius-md);
}

.sg-skeleton-rounded-full {
  border-radius: var(--sg-radius-pill);
}

@keyframes sg-skeleton-shimmer {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

/* —— Alert / Callout —— */
.sg-alert {
  display: flex;
  align-items: flex-start;
  gap: var(--sg-space-3);
  padding: var(--sg-space-3) var(--sg-space-4);
  border-radius: var(--sg-radius-md);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  color: var(--sg-fg);
  font-size: var(--sg-text-sm);
  line-height: var(--sg-leading-normal);
}

.sg-alert-marker {
  flex-shrink: 0;
  width: 0.5rem;
  height: 0.5rem;
  margin-top: 0.4rem;
  border-radius: 50%;
  background: currentColor;
}

.sg-alert-icon {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  margin-top: 0.1rem;
}

.sg-alert-body {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--sg-space-1);
}

.sg-alert-title {
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
}

.sg-alert-content {
  color: var(--sg-fg-muted);
}

.sg-alert-info {
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-accent-soft) 70%, var(--sg-surface-frost));
  color: var(--sg-fg);
}

.sg-alert-info .sg-alert-marker,
.sg-alert-info .sg-alert-icon {
  color: var(--sg-accent);
}

.sg-alert-success {
  border-color: color-mix(in srgb, var(--sg-success) 40%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-success) 12%, var(--sg-surface-frost));
}

.sg-alert-success .sg-alert-marker,
.sg-alert-success .sg-alert-icon {
  color: var(--sg-success);
}

.sg-alert-warning {
  border-color: color-mix(in srgb, var(--sg-warning) 40%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-warning) 12%, var(--sg-surface-frost));
}

.sg-alert-warning .sg-alert-marker,
.sg-alert-warning .sg-alert-icon {
  color: var(--sg-warning);
}

.sg-alert-danger {
  border-color: color-mix(in srgb, var(--sg-danger) 40%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-danger) 12%, var(--sg-surface-frost));
}

.sg-alert-danger .sg-alert-marker,
.sg-alert-danger .sg-alert-icon {
  color: var(--sg-danger);
}

/* —— Progress (linear) —— */
.sg-progress {
  display: block;
  width: 100%;
  color: var(--sg-accent);
}

.sg-progress-track {
  position: relative;
  width: 100%;
  height: 0.5rem;
  overflow: hidden;
  border-radius: var(--sg-radius-pill);
  background: color-mix(in srgb, var(--sg-fg-muted) 12%, var(--sg-surface-solid));
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--sg-gloss-highlight) 55%, transparent);
}

.sg-progress-sm .sg-progress-track {
  height: 0.3rem;
}

.sg-progress-lg .sg-progress-track {
  height: 0.7rem;
}

.sg-progress-look-solid .sg-progress-track {
  background: var(--sg-surface-solid);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  box-shadow: none;
}

.sg-progress-look-glass .sg-progress-track {
  background: var(--sg-surface-frost);
  border: var(--sg-border-width) solid var(--sg-border-glass);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-progress-look-accent .sg-progress-track {
  height: 0.6rem;
  background: color-mix(in srgb, var(--sg-accent) 14%, var(--sg-surface-solid));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--sg-gloss-highlight) 50%, transparent),
    0 0 10px color-mix(in srgb, currentColor 12%, transparent);
}

.sg-progress-look-accent .sg-progress-fill {
  box-shadow:
    0 0 0 1px color-mix(in srgb, currentColor 25%, transparent),
    0 0 12px color-mix(in srgb, currentColor 40%, transparent);
}

.sg-progress-look-striped .sg-progress-fill {
  background-image:
    linear-gradient(
      45deg,
      color-mix(in srgb, #fff 18%, transparent) 25%,
      transparent 25%,
      transparent 50%,
      color-mix(in srgb, #fff 18%, transparent) 50%,
      color-mix(in srgb, #fff 18%, transparent) 75%,
      transparent 75%,
      transparent
    ),
    linear-gradient(90deg, color-mix(in srgb, currentColor 88%, transparent), currentColor);
  background-size: 0.75rem 0.75rem, 100% 100%;
  animation: sg-progress-stripes 0.9s linear infinite;
}

.sg-progress-look-striped.sg-progress-indeterminate .sg-progress-fill {
  animation:
    sg-progress-indeterminate 1.2s ease-in-out infinite,
    sg-progress-stripes 0.9s linear infinite;
}

@keyframes sg-progress-stripes {
  0% {
    background-position: 0 0, 0 0;
  }
  100% {
    background-position: 0.75rem 0, 0 0;
  }
}

/* Progress semantic fill */
.sg-progress-success {
  color: var(--sg-success);
}

.sg-progress-warning {
  color: var(--sg-warning);
}

.sg-progress-danger {
  color: var(--sg-danger);
}

.sg-progress-muted {
  color: var(--sg-fg-muted);
}

.sg-progress-fill {
  height: 100%;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, currentColor 88%, transparent),
    currentColor
  );
  box-shadow: 0 0 0 1px color-mix(in srgb, currentColor 18%, transparent);
  transition: width 180ms ease;
}

.sg-progress-indeterminate .sg-progress-fill {
  width: 36%;
  transition: none;
  animation: sg-progress-indeterminate 1.2s ease-in-out infinite;
}

@keyframes sg-progress-indeterminate {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(320%);
  }
}

/* —— StatusDot —— */
.sg-status-dot {
  --sg-status-dot-color: var(--sg-success);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 0.625rem;
  height: 0.625rem;
  flex-shrink: 0;
  vertical-align: middle;
  color: var(--sg-status-dot-color);
}

.sg-status-dot-sm {
  width: 0.45rem;
  height: 0.45rem;
}

.sg-status-dot-lg {
  width: 0.8rem;
  height: 0.8rem;
}

.sg-status-dot-core {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: currentColor;
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--sg-surface-solid) 70%, transparent),
    0 0 0 2px color-mix(in srgb, currentColor 22%, transparent);
}

.sg-status-dot-online {
  --sg-status-dot-color: var(--sg-success);
}

.sg-status-dot-busy {
  --sg-status-dot-color: var(--sg-danger);
}

.sg-status-dot-offline {
  --sg-status-dot-color: var(--sg-fg-muted);
}

.sg-status-dot-away {
  --sg-status-dot-color: var(--sg-warning);
}

/* StatusDot looks */
.sg-status-dot-look-solid .sg-status-dot-core {
  box-shadow: none;
}

.sg-status-dot-look-outline .sg-status-dot-core {
  background: transparent;
  box-shadow: none;
  border: 2px solid currentColor;
}

.sg-status-dot-look-glow .sg-status-dot-core {
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--sg-surface-solid) 55%, transparent),
    0 0 0 3px color-mix(in srgb, currentColor 28%, transparent),
    0 0 10px color-mix(in srgb, currentColor 55%, transparent);
}

/* custom color: set --sg-status-dot-color via inline style */

.sg-status-dot-pulse {
  position: relative;
}

.sg-status-dot-pulse::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  opacity: 0.55;
  animation: sg-status-dot-ping 1.6s ease-out infinite;
}

@keyframes sg-status-dot-ping {
  0% {
    transform: scale(0.85);
    opacity: 0.55;
  }
  70% {
    transform: scale(1.55);
    opacity: 0;
  }
  100% {
    transform: scale(1.55);
    opacity: 0;
  }
}

/* —— Slider —— */
.sg-slider {
  --sg-slider-pct: 0%;
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: var(--sg-touch-min);
  color: var(--sg-accent);
}

.sg-slider[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

.sg-slider-label-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sg-space-3);
}

.sg-slider-value {
  font-size: var(--sg-text-sm);
  font-variant-numeric: tabular-nums;
  color: var(--sg-fg-muted);
}

.sg-slider-input {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 0.45rem;
  margin: 0;
  border-radius: var(--sg-radius-pill);
  background: linear-gradient(
    90deg,
    currentColor 0%,
    currentColor var(--sg-slider-pct),
    color-mix(in srgb, var(--sg-fg-muted) 14%, var(--sg-surface-solid))
      var(--sg-slider-pct),
    color-mix(in srgb, var(--sg-fg-muted) 14%, var(--sg-surface-solid)) 100%
  );
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--sg-gloss-highlight) 50%, transparent);
  cursor: pointer;
}

.sg-slider-sm .sg-slider-input {
  height: 0.3rem;
}

.sg-slider-lg .sg-slider-input {
  height: 0.6rem;
}

.sg-slider-input:focus {
  outline: none;
}

.sg-slider-input:focus-visible {
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--sg-gloss-highlight) 50%, transparent),
    0 0 0 3px var(--sg-ring-soft);
}

.sg-slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 1.15rem;
  height: 1.15rem;
  margin-top: 0;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--sg-surface-solid) 80%, transparent);
  background: currentColor;
  box-shadow:
    0 1px 3px color-mix(in srgb, var(--sg-fg) 18%, transparent),
    0 0 0 1px color-mix(in srgb, currentColor 25%, transparent);
  cursor: grab;
}

.sg-slider-sm .sg-slider-input::-webkit-slider-thumb {
  width: 0.95rem;
  height: 0.95rem;
}

.sg-slider-lg .sg-slider-input::-webkit-slider-thumb {
  width: 1.35rem;
  height: 1.35rem;
}

.sg-slider-input::-moz-range-thumb {
  width: 1.15rem;
  height: 1.15rem;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--sg-surface-solid) 80%, transparent);
  background: currentColor;
  box-shadow:
    0 1px 3px color-mix(in srgb, var(--sg-fg) 18%, transparent),
    0 0 0 1px color-mix(in srgb, currentColor 25%, transparent);
  cursor: grab;
}

.sg-slider-input::-moz-range-track {
  height: 0.45rem;
  border-radius: var(--sg-radius-pill);
  background: transparent;
}

/* Slider looks */
.sg-slider-look-solid {
  color: var(--sg-fg);
}

.sg-slider-look-solid .sg-slider-input {
  background: linear-gradient(
    90deg,
    var(--sg-accent) 0%,
    var(--sg-accent) var(--sg-slider-pct),
    var(--sg-surface-solid) var(--sg-slider-pct),
    var(--sg-surface-solid) 100%
  );
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
}

.sg-slider-look-solid .sg-slider-input::-webkit-slider-thumb {
  background: var(--sg-surface-solid);
  border: 2px solid var(--sg-accent);
  box-shadow: 0 1px 4px color-mix(in srgb, var(--sg-fg) 16%, transparent);
}

.sg-slider-look-solid .sg-slider-input::-moz-range-thumb {
  background: var(--sg-surface-solid);
  border: 2px solid var(--sg-accent);
}

.sg-slider-look-glass {
  color: var(--sg-accent);
}

.sg-slider-look-glass .sg-slider-input {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--sg-accent) 75%, transparent) 0%,
    color-mix(in srgb, var(--sg-accent) 75%, transparent) var(--sg-slider-pct),
    var(--sg-surface-frost) var(--sg-slider-pct),
    var(--sg-surface-frost) 100%
  );
  border: var(--sg-border-width) solid var(--sg-border-glass);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-slider-look-glass .sg-slider-input::-webkit-slider-thumb {
  background: var(--sg-surface-frost);
  border: 2px solid var(--sg-accent);
  backdrop-filter: blur(6px);
}

.sg-slider-look-glass .sg-slider-input::-moz-range-thumb {
  background: var(--sg-surface-frost);
  border: 2px solid var(--sg-accent);
}

.sg-slider-look-accent {
  color: var(--sg-accent);
}

.sg-slider-look-accent .sg-slider-input {
  height: 0.55rem;
  background: linear-gradient(
    90deg,
    var(--sg-accent) 0%,
    color-mix(in srgb, var(--sg-accent) 70%, #fff) var(--sg-slider-pct),
    color-mix(in srgb, var(--sg-accent) 16%, var(--sg-surface-solid))
      var(--sg-slider-pct),
    color-mix(in srgb, var(--sg-accent) 16%, var(--sg-surface-solid)) 100%
  );
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, var(--sg-gloss-highlight) 60%, transparent),
    0 0 12px color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

.sg-slider-look-accent .sg-slider-input::-webkit-slider-thumb {
  width: 1.3rem;
  height: 1.3rem;
  background: var(--sg-accent);
  border: 3px solid var(--sg-surface-solid);
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--sg-accent) 35%, transparent),
    0 2px 8px color-mix(in srgb, var(--sg-accent) 40%, transparent);
}

.sg-slider-look-accent .sg-slider-input::-moz-range-thumb {
  width: 1.3rem;
  height: 1.3rem;
  background: var(--sg-accent);
  border: 3px solid var(--sg-surface-solid);
}

/* —— NumberInput ——
   Softglass quantity pattern: [ − ]  value  [ + ]
   Soft pill steppers + solid center field (not Windows vertical spinner).
*/
.sg-number-input {
  display: inline-grid;
  grid-template-columns: auto minmax(3.25rem, 1fr) auto;
  align-items: center;
  gap: var(--sg-space-2);
  width: 100%;
  max-width: 14rem;
  padding: 0.25rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  transition: border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-number-input.sg-input-block {
  max-width: none;
}

.sg-number-input-plain {
  grid-template-columns: 1fr;
  max-width: none;
  border-radius: var(--sg-radius-sm);
  background: var(--sg-surface-solid);
  padding: 0;
  box-shadow: none;
}

.sg-number-input:focus-within {
  border-color: var(--sg-accent);
  box-shadow:
    inset 0 1px 0 var(--sg-gloss-highlight),
    0 0 0 3px var(--sg-ring-soft);
}

.sg-number-input[data-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow:
    inset 0 1px 0 var(--sg-gloss-highlight),
    0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-number-input[data-disabled="true"] {
  opacity: 0.55;
}

.sg-number-input-field {
  width: 100%;
  min-width: 0;
  min-height: calc(var(--sg-touch-min) - 0.5rem);
  margin: 0;
  padding: 0.35rem 0.5rem;
  border: 0;
  border-radius: var(--sg-radius-sm);
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-base);
  font-variant-numeric: tabular-nums;
  font-weight: var(--sg-font-weight-medium);
  text-align: center;
  line-height: 1.2;
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
}

.sg-number-input-sm .sg-number-input-field {
  min-height: 1.85rem;
  font-size: var(--sg-text-sm);
}

.sg-number-input-lg .sg-number-input-field {
  min-height: 2.5rem;
  font-size: var(--sg-text-lg);
}

.sg-number-input-plain .sg-number-input-field {
  min-height: var(--sg-touch-min);
  padding: 0.625rem 1rem;
  text-align: start;
  border-radius: var(--sg-radius-sm);
  box-shadow: none;
  font-weight: var(--sg-font-weight-normal);
}

.sg-number-input-field:focus {
  outline: none;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 45%, var(--sg-border-subtle));
}

.sg-number-input-field:disabled {
  cursor: not-allowed;
}

/* Hide native number spinners — custom soft steppers */
.sg-number-input-field::-webkit-outer-spin-button,
.sg-number-input-field::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.sg-number-input-field[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}

.sg-number-input-step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: calc(var(--sg-touch-min) - 0.35rem);
  height: calc(var(--sg-touch-min) - 0.35rem);
  margin: 0;
  padding: 0;
  border: var(--sg-border-width) solid
    color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-subtle));
  border-radius: 50%;
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  font-size: 1.15rem;
  font-weight: var(--sg-font-weight-semibold);
  line-height: 1;
  cursor: pointer;
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    transform var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-number-input-sm .sg-number-input-step {
  width: 1.85rem;
  height: 1.85rem;
  font-size: 1rem;
}

.sg-number-input-lg .sg-number-input-step {
  width: 2.5rem;
  height: 2.5rem;
  font-size: 1.25rem;
}

.sg-number-input-step:hover:not(:disabled) {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
}

.sg-number-input-step:active:not(:disabled) {
  transform: scale(0.96);
}

.sg-number-input-step:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-number-input-step:disabled {
  opacity: 0.35;
  cursor: not-allowed;
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, var(--sg-surface-solid));
  border-color: var(--sg-border-subtle);
  color: var(--sg-fg-muted);
  box-shadow: none;
}

/* NumberInput looks */
.sg-number-input-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-number-input-look-solid .sg-number-input-step {
  background: color-mix(in srgb, var(--sg-fg-muted) 10%, var(--sg-surface-solid));
  border-color: var(--sg-border-subtle);
  color: var(--sg-fg);
  box-shadow: none;
}

.sg-number-input-look-solid .sg-number-input-step:hover:not(:disabled) {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
}

.sg-number-input-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-subtle));
  box-shadow: none;
}

.sg-number-input-look-outline .sg-number-input-field {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
}

.sg-number-input-look-outline .sg-number-input-step {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-subtle));
  color: var(--sg-accent);
  box-shadow: none;
}

.sg-number-input-look-outline .sg-number-input-step:hover:not(:disabled) {
  background: var(--sg-accent-soft);
  border-color: var(--sg-accent);
  color: var(--sg-fg);
}

.sg-number-input-look-ghost {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  padding: 0;
  gap: var(--sg-space-1);
}

.sg-number-input-look-ghost .sg-number-input-field {
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, transparent);
  box-shadow: none;
  border-radius: var(--sg-radius-pill);
}

.sg-number-input-look-ghost .sg-number-input-step {
  background: transparent;
  border-color: transparent;
  color: var(--sg-fg-muted);
  box-shadow: none;
}

.sg-number-input-look-ghost .sg-number-input-step:hover:not(:disabled) {
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
}

.sg-number-input-look-ghost:focus-within {
  box-shadow: none;
}

.sg-number-input-look-ghost:focus-within .sg-number-input-field {
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

@media (prefers-reduced-motion: reduce) {
  .sg-number-input-step {
    transition: none;
  }

  .sg-number-input-step:active:not(:disabled) {
    transform: none;
  }
}

/* —— FileField —— */
.sg-file-field {
  display: grid;
  gap: var(--sg-space-2);
  width: 100%;
}

.sg-file-field[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

.sg-file-field-trigger {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--sg-space-3);
  min-height: var(--sg-touch-min);
  padding: 0.4rem 0.5rem 0.4rem 0.4rem;
  border-radius: var(--sg-radius-sm);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-solid);
  transition: border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-file-field-trigger:focus-within {
  border-color: var(--sg-accent);
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-file-field[data-invalid="true"] .sg-file-field-trigger {
  border-color: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-file-field-sm .sg-file-field-trigger {
  min-height: 2.25rem;
}

.sg-file-field-lg .sg-file-field-trigger {
  min-height: 3rem;
}

.sg-file-field-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
  font-size: 0;
}

.sg-file-field-button {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.4rem 0.85rem;
  border-radius: var(--sg-radius-xs);
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  border: var(--sg-border-width) solid
    color-mix(in srgb, var(--sg-accent) 22%, transparent);
  pointer-events: none;
}

.sg-file-field-summary {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg-muted);
  pointer-events: none;
}

.sg-file-field-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--sg-space-1);
}

.sg-file-field-item {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: var(--sg-space-2);
  padding: 0.45rem 0.65rem;
  border-radius: var(--sg-radius-xs);
  background: color-mix(in srgb, var(--sg-fg-muted) 6%, var(--sg-surface-solid));
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  font-size: var(--sg-text-sm);
}

.sg-file-field-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--sg-fg);
}

.sg-file-field-meta {
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-xs);
  font-variant-numeric: tabular-nums;
}

.sg-file-field-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--sg-radius-xs);
  background: transparent;
  color: var(--sg-fg-muted);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.sg-file-field-remove:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-danger) 12%, transparent);
  color: var(--sg-danger);
}

.sg-file-field-clear {
  justify-self: start;
  margin: 0;
  padding: 0.2rem 0.4rem;
  border: 0;
  background: transparent;
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-xs);
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.sg-file-field-clear:hover:not(:disabled) {
  color: var(--sg-fg);
}

/* FileField looks */
.sg-file-field-look-soft .sg-file-field-trigger {
  background: var(--sg-surface-frost);
  border-color: var(--sg-border-glass);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  border-radius: var(--sg-radius-md);
}

.sg-file-field-look-soft .sg-file-field-button {
  background: color-mix(in srgb, var(--sg-accent) 18%, transparent);
  border-color: color-mix(in srgb, var(--sg-accent) 28%, transparent);
  border-radius: var(--sg-radius-pill);
}

.sg-file-field-look-dashed .sg-file-field-trigger {
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: var(--sg-space-2);
  min-height: 7.5rem;
  padding: var(--sg-space-5);
  border-style: dashed;
  border-width: 1.5px;
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-accent-soft) 45%, var(--sg-surface-solid));
  border-radius: var(--sg-radius-md);
  text-align: center;
}

.sg-file-field-look-dashed .sg-file-field-button {
  background: var(--sg-surface-solid);
  border-color: color-mix(in srgb, var(--sg-accent) 25%, var(--sg-border-subtle));
  border-radius: var(--sg-radius-pill);
  padding: 0.5rem 1.1rem;
}

.sg-file-field-look-dashed .sg-file-field-summary {
  white-space: normal;
  text-align: center;
  max-width: 18rem;
}

.sg-file-field-look-ghost .sg-file-field-trigger {
  background: transparent;
  border-color: transparent;
  border-bottom: var(--sg-border-width) solid var(--sg-border-subtle);
  border-radius: 0;
  padding-inline: 0;
  box-shadow: none;
}

.sg-file-field-look-ghost .sg-file-field-trigger:focus-within {
  border-bottom-color: var(--sg-accent);
  box-shadow: none;
}

.sg-file-field-look-ghost .sg-file-field-button {
  background: transparent;
  border-color: transparent;
  color: var(--sg-accent);
  text-decoration: underline;
  text-underline-offset: 0.15em;
  padding-inline: 0.25rem;
}

.sg-file-field-look-ghost[data-invalid="true"] .sg-file-field-trigger {
  border-bottom-color: var(--sg-danger);
  box-shadow: none;
}

/* —— VisuallyHidden —— */
.sg-visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* —— CloseButton —— */
.sg-close-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1.75rem;
  height: 1.75rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--sg-fg-muted);
  line-height: 0;
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-close-btn-glyph {
  display: block;
  font-size: 1.15rem;
  line-height: 1;
}

.sg-close-btn:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-fg-muted) 12%, transparent);
  color: var(--sg-fg);
}

.sg-close-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-close-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.sg-close-btn-sm {
  width: 1.4rem;
  height: 1.4rem;
}

.sg-close-btn-sm .sg-close-btn-glyph {
  font-size: 1rem;
}

.sg-close-btn-lg {
  width: 2.1rem;
  height: 2.1rem;
}

.sg-close-btn-lg .sg-close-btn-glyph {
  font-size: 1.35rem;
}

.sg-close-btn-look-soft {
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
}

.sg-close-btn-look-soft:hover:not(:disabled) {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-close-btn-look-solid {
  background: var(--sg-surface-solid);
  color: var(--sg-fg-muted);
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
}

.sg-close-btn-look-solid:hover:not(:disabled) {
  color: var(--sg-fg);
}

.sg-close-btn-look-danger {
  background: color-mix(in srgb, var(--sg-danger) 12%, transparent);
  color: var(--sg-danger);
}

.sg-close-btn-look-danger:hover:not(:disabled) {
  background: var(--sg-danger);
  color: #fff;
}

/* —— Link —— */
.sg-link {
  color: var(--sg-accent);
  font-weight: var(--sg-font-weight-medium);
  text-decoration: none;
  text-underline-offset: 0.15em;
  transition: color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-link:hover {
  color: var(--sg-accent-hover);
  text-decoration: underline;
}

.sg-link:focus-visible {
  outline: none;
  border-radius: 2px;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-link-muted {
  color: var(--sg-fg-muted);
  font-weight: var(--sg-font-weight-normal);
}

.sg-link-muted:hover {
  color: var(--sg-fg);
}

.sg-link-subtle {
  color: var(--sg-fg);
  font-weight: var(--sg-font-weight-normal);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--sg-fg-muted) 45%, transparent);
}

.sg-link-subtle:hover {
  color: var(--sg-accent);
  text-decoration-color: var(--sg-accent);
}

.sg-link-underline {
  text-decoration: underline;
}

.sg-link-external {
  font-size: 0.85em;
  opacity: 0.75;
}

/* —— Chip ——
   Outer span is the visual pill. Trigger + × are siblings (never nested buttons).
   Fixed height + flex center keeps remove glyph aligned on every look. */
.sg-chip {
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  max-width: 100%;
  height: 2rem;
  box-sizing: border-box;
  padding: 0 0.15rem 0 0;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-subtle));
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1;
  vertical-align: middle;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-chip-sm {
  height: 1.65rem;
  font-size: var(--sg-text-xs);
}

.sg-chip-lg {
  height: 2.35rem;
  font-size: var(--sg-text-base);
}

.sg-chip-disabled,
.sg-chip[data-disabled="true"] {
  opacity: 0.5;
  pointer-events: none;
}

.sg-chip-trigger,
.sg-chip-static {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  height: 100%;
  margin: 0;
  padding: 0 0.75rem;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  line-height: 1;
  cursor: pointer;
  border-radius: 999px;
  min-width: 0;
}

.sg-chip-static {
  cursor: default;
}

.sg-chip-removable .sg-chip-trigger,
.sg-chip-removable .sg-chip-static {
  padding-right: 0.35rem;
  border-radius: 999px 0 0 999px;
}

.sg-chip-sm .sg-chip-trigger,
.sg-chip-sm .sg-chip-static {
  padding-left: 0.55rem;
  padding-right: 0.55rem;
}

.sg-chip-sm.sg-chip-removable .sg-chip-trigger,
.sg-chip-sm.sg-chip-removable .sg-chip-static {
  padding-right: 0.25rem;
}

.sg-chip-lg .sg-chip-trigger,
.sg-chip-lg .sg-chip-static {
  padding-left: 0.9rem;
  padding-right: 0.9rem;
}

.sg-chip-lg.sg-chip-removable .sg-chip-trigger,
.sg-chip-lg.sg-chip-removable .sg-chip-static {
  padding-right: 0.4rem;
}

.sg-chip-trigger:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--sg-ring-soft);
}

.sg-chip-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sg-chip-leading {
  display: inline-flex;
  flex-shrink: 0;
}

/* Dedicated remove control — not CloseButton (avoids size/baseline drift) */
.sg-chip-x {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 1.5rem;
  height: 1.5rem;
  margin: 0 0.2rem 0 0;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font-size: 1rem;
  line-height: 1;
  cursor: pointer;
  opacity: 0.75;
}

.sg-chip-sm .sg-chip-x {
  width: 1.25rem;
  height: 1.25rem;
  font-size: 0.9rem;
}

.sg-chip-lg .sg-chip-x {
  width: 1.7rem;
  height: 1.7rem;
  font-size: 1.1rem;
}

.sg-chip-x:hover:not(:disabled) {
  opacity: 1;
  background: color-mix(in srgb, var(--sg-fg) 12%, transparent);
}

.sg-chip-x:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--sg-ring-soft);
}

.sg-chip-selected,
.sg-chip[data-selected="true"] {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-chip-selected .sg-chip-x:hover:not(:disabled),
.sg-chip[data-selected="true"] .sg-chip-x:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-accent-fg) 20%, transparent);
}

.sg-chip-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-chip-look-solid.sg-chip-selected,
.sg-chip-look-solid[data-selected="true"] {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
}

.sg-chip-look-outline {
  background: var(--sg-surface-solid);
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-subtle));
  box-shadow: none;
}

.sg-chip-look-outline.sg-chip-selected,
.sg-chip-look-outline[data-selected="true"] {
  background: var(--sg-accent-soft);
  border-color: var(--sg-accent);
  color: var(--sg-fg);
  box-shadow: none;
}

/* Glass must stay readable on light languages (frost alone washes out). */
.sg-chip-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 55%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 14%, var(--sg-border-subtle));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 55%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
  backdrop-filter: blur(10px);
}

.sg-chip-look-glass.sg-chip-selected,
.sg-chip-look-glass[data-selected="true"] {
  background: color-mix(in srgb, var(--sg-accent) 55%, var(--sg-surface-solid));
  border-color: color-mix(in srgb, var(--sg-accent) 50%, transparent);
  color: var(--sg-accent-fg);
  box-shadow:
    inset 0 1px 0 var(--sg-gloss-highlight),
    0 0 0 1px color-mix(in srgb, var(--sg-accent) 25%, transparent);
}

.sg-chip-look-glow {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 40%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-accent) 16%, transparent);
}

.sg-chip-look-glow.sg-chip-selected,
.sg-chip-look-glow[data-selected="true"] {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--sg-accent) 28%, transparent),
    inset 0 1px 0 var(--sg-gloss-highlight);
}

/* —— Password / Search — ride on .sg-input-group (proven shell) —— */
.sg-password-input,
.sg-search-input {
  /* inherits .sg-input-group flex */
}

.sg-password-input[data-invalid="true"],
.sg-search-input[data-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

.sg-password-input-soft,
.sg-search-input-soft {
  border-radius: var(--sg-radius-pill);
  background: color-mix(in srgb, var(--sg-surface-solid) 82%, var(--sg-accent-soft));
  border-color: color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-subtle));
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-password-input-glass,
.sg-search-input-glass {
  border-radius: var(--sg-radius-md);
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, var(--sg-border-subtle));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
  backdrop-filter: blur(10px);
}

.sg-password-toggle {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  margin: 0;
  padding: 0 1rem;
  border: 0;
  border-left: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
}

.sg-password-toggle:hover:not(:disabled) {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-password-toggle:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sg-password-toggle:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--sg-ring-soft);
}

.sg-search-addon {
  font-weight: var(--sg-font-weight-medium);
  color: var(--sg-fg-muted);
}

.sg-search-clear {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding: 0 0.85rem;
  border: 0;
  border-left: var(--sg-border-width) solid var(--sg-border-subtle);
  background: transparent;
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1;
  cursor: pointer;
  white-space: nowrap;
}

.sg-search-clear:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-danger) 10%, transparent);
  color: var(--sg-danger);
}

.sg-search-clear:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--sg-ring-soft);
}

.sg-search-input-field::-webkit-search-cancel-button,
.sg-search-input-field::-webkit-search-decoration {
  -webkit-appearance: none;
  appearance: none;
}

/* —— CircularProgress —— */
.sg-circular-progress {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--sg-accent);
  flex-shrink: 0;
  vertical-align: middle;
}

.sg-circular-progress-svg {
  display: block;
  transform: rotate(-90deg);
}

.sg-circular-progress-track {
  stroke: color-mix(in srgb, var(--sg-fg-muted) 16%, var(--sg-surface-solid));
}

.sg-circular-progress-fill {
  stroke: currentColor;
  transition: stroke-dashoffset 180ms ease;
}

.sg-circular-progress-value {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: var(--sg-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  color: var(--sg-fg);
  line-height: 1;
}

.sg-circular-progress-lg .sg-circular-progress-value {
  font-size: 0.85rem;
}

.sg-circular-progress-sm .sg-circular-progress-value {
  font-size: 0.6rem;
}

.sg-circular-progress-success {
  color: var(--sg-success);
}

.sg-circular-progress-warning {
  color: var(--sg-warning);
}

.sg-circular-progress-danger {
  color: var(--sg-danger);
}

.sg-circular-progress-muted {
  color: var(--sg-fg-muted);
}

.sg-circular-progress-look-solid .sg-circular-progress-track {
  stroke: var(--sg-surface-solid);
  stroke-width: inherit;
  /* thicker track feel via filter-like opacity edge */
  opacity: 1;
  filter: drop-shadow(0 0 0 var(--sg-border-subtle));
}

.sg-circular-progress-look-solid {
  filter: none;
}

.sg-circular-progress-look-solid .sg-circular-progress-track {
  stroke: color-mix(in srgb, var(--sg-fg-muted) 28%, var(--sg-surface-solid));
}

.sg-circular-progress-look-glass .sg-circular-progress-track {
  stroke: color-mix(in srgb, var(--sg-accent) 18%, var(--sg-surface-solid));
}

.sg-circular-progress-look-glass {
  filter: drop-shadow(0 0 6px color-mix(in srgb, currentColor 22%, transparent));
}

.sg-circular-progress-look-accent .sg-circular-progress-track {
  stroke: color-mix(in srgb, var(--sg-accent) 22%, var(--sg-surface-solid));
}

.sg-circular-progress-look-accent .sg-circular-progress-fill {
  filter: drop-shadow(0 0 4px color-mix(in srgb, currentColor 45%, transparent));
}

.sg-circular-progress-indeterminate .sg-circular-progress-svg {
  animation: sg-circular-spin 0.9s linear infinite;
}

.sg-circular-progress-indeterminate .sg-circular-progress-fill {
  transition: none;
}

@keyframes sg-circular-spin {
  to {
    transform: rotate(270deg);
  }
}

/* —— SegmentedControl —— */
.sg-segmented {
  display: inline-flex;
  align-items: stretch;
  padding: 0.2rem;
  gap: 0.15rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, var(--sg-surface-solid));
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 40%, transparent);
  vertical-align: middle;
}

.sg-segmented-block {
  display: flex;
  width: 100%;
}

.sg-segmented-block .sg-segmented-item {
  flex: 1;
}

.sg-segmented[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

.sg-segmented-item {
  appearance: none;
  margin: 0;
  padding: 0.45rem 0.9rem;
  border: 0;
  border-radius: var(--sg-radius-pill);
  background: transparent;
  color: var(--sg-fg-muted);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1.2;
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-segmented-sm .sg-segmented-item {
  padding: 0.3rem 0.65rem;
  font-size: var(--sg-text-xs);
}

.sg-segmented-lg .sg-segmented-item {
  padding: 0.55rem 1.1rem;
  font-size: var(--sg-text-base);
}

.sg-segmented-item:hover:not(:disabled):not(.sg-segmented-item-selected) {
  color: var(--sg-fg);
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, transparent);
}

.sg-segmented-item:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-segmented-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sg-segmented-item-selected {
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  box-shadow:
    0 1px 2px color-mix(in srgb, var(--sg-fg) 10%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 55%, transparent);
}

.sg-segmented-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-segmented-look-solid .sg-segmented-item-selected {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  box-shadow: none;
}

.sg-segmented-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 30%, var(--sg-border-subtle));
  box-shadow: none;
}

.sg-segmented-look-outline .sg-segmented-item-selected {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 35%, transparent);
}

.sg-segmented-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 55%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, var(--sg-border-subtle));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
  backdrop-filter: blur(10px);
}

.sg-segmented-look-glass .sg-segmented-item-selected {
  background: color-mix(in srgb, var(--sg-accent) 18%, var(--sg-surface-solid));
  color: var(--sg-fg);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 28%, transparent);
}

/* —— Kbd —— */
.sg-kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.4em;
  padding: 0.15rem 0.4rem;
  border-radius: var(--sg-radius-xs);
  border: 1px solid color-mix(in srgb, var(--sg-fg-muted) 22%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, var(--sg-surface-solid));
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--sg-fg) 10%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: 0.75rem;
  font-weight: var(--sg-font-weight-medium);
  line-height: 1.2;
  vertical-align: middle;
}

.sg-kbd-sm {
  padding: 0.1rem 0.3rem;
  font-size: 0.65rem;
}

.sg-kbd-lg {
  padding: 0.25rem 0.55rem;
  font-size: 0.85rem;
}

.sg-kbd-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-kbd-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-subtle));
  box-shadow: none;
  color: var(--sg-accent);
}

.sg-kbd-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 45%, transparent);
  backdrop-filter: blur(8px);
}

/* —— Code —— */
.sg-code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.9em;
  padding: 0.12em 0.35em;
  border-radius: var(--sg-radius-xs);
  background: color-mix(in srgb, var(--sg-fg-muted) 10%, var(--sg-surface-solid));
  border: 1px solid color-mix(in srgb, var(--sg-fg-muted) 12%, transparent);
  color: var(--sg-fg);
}

.sg-code-block {
  display: block;
  overflow: auto;
  margin: 0;
  padding: 0.85rem 1rem;
  font-size: var(--sg-text-sm);
  line-height: 1.5;
  white-space: pre;
}

.sg-code-block code {
  padding: 0;
  border: 0;
  background: transparent;
  font: inherit;
}

.sg-code-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-code-look-accent {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 28%, transparent);
  color: var(--sg-fg);
}

.sg-code-look-muted {
  background: transparent;
  border-color: transparent;
  color: var(--sg-fg-muted);
  padding-inline: 0.15em;
}

/* —— SkipLink ——
   clip-based hide (not translate) so overflow:hidden parents cannot swallow it.
   alwaysVisible / .sg-skip-link-visible for docs demos. */
.sg-skip-link {
  position: fixed;
  top: 0.75rem;
  z-index: 10000;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.55rem 0.95rem;
  border-radius: var(--sg-radius-sm);
  border: 1px solid transparent;
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  line-height: 1.2;
  text-decoration: none;
  white-space: nowrap;
  /* visually hide until focus / alwaysVisible */
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  border: 0;
}

.sg-skip-link-start {
  left: 0.75rem;
  right: auto;
  transform: none;
}

.sg-skip-link-center {
  left: 50%;
  right: auto;
  transform: translateX(-50%);
}

.sg-skip-link-end {
  left: auto;
  right: 0.75rem;
  transform: none;
}

.sg-skip-link:focus,
.sg-skip-link:focus-visible,
.sg-skip-link.sg-skip-link-visible,
.sg-skip-link[data-always-visible="true"] {
  width: auto;
  height: auto;
  margin: 0;
  padding: 0.55rem 0.95rem;
  overflow: visible;
  clip: auto;
  clip-path: none;
  border: 1px solid transparent;
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-skip-link-center:focus,
.sg-skip-link-center:focus-visible,
.sg-skip-link-center.sg-skip-link-visible,
.sg-skip-link-center[data-always-visible="true"] {
  transform: translateX(-50%);
}

/* SkipLink looks (when visible) */
.sg-skip-link-look-soft:focus,
.sg-skip-link-look-soft:focus-visible,
.sg-skip-link-look-soft.sg-skip-link-visible,
.sg-skip-link-look-soft[data-always-visible="true"] {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  border-color: color-mix(in srgb, var(--sg-accent) 30%, transparent);
}

.sg-skip-link-look-outline:focus,
.sg-skip-link-look-outline:focus-visible,
.sg-skip-link-look-outline.sg-skip-link-visible,
.sg-skip-link-look-outline[data-always-visible="true"] {
  background: var(--sg-surface-solid);
  color: var(--sg-accent);
  border-color: color-mix(in srgb, var(--sg-accent) 45%, var(--sg-border-subtle));
}

.sg-skip-link-look-glass:focus,
.sg-skip-link-look-glass:focus-visible,
.sg-skip-link-look-glass.sg-skip-link-visible,
.sg-skip-link-look-glass[data-always-visible="true"] {
  background: color-mix(in srgb, var(--sg-surface-solid) 55%, transparent);
  color: var(--sg-fg);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, transparent);
  backdrop-filter: blur(10px);
  box-shadow:
    0 0 0 3px var(--sg-ring-soft),
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent);
}

/* —— PinInput —— */
.sg-pin {
  display: inline-flex;
  gap: 0.45rem;
  align-items: center;
  vertical-align: middle;
}

.sg-pin[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

.sg-pin-cell {
  width: 2.5rem;
  height: 2.75rem;
  margin: 0;
  padding: 0;
  border-radius: var(--sg-radius-sm);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-solid);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-lg);
  font-weight: var(--sg-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  text-align: center;
  line-height: 1;
  transition:
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-pin-sm .sg-pin-cell {
  width: 2rem;
  height: 2.25rem;
  font-size: var(--sg-text-base);
}

.sg-pin-lg .sg-pin-cell {
  width: 3rem;
  height: 3.25rem;
  font-size: 1.35rem;
}

.sg-pin-cell:focus {
  outline: none;
  border-color: var(--sg-accent);
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-pin[data-invalid="true"] .sg-pin-cell {
  border-color: var(--sg-danger);
}

.sg-pin-look-soft .sg-pin-cell {
  background: color-mix(in srgb, var(--sg-surface-solid) 82%, var(--sg-accent-soft));
  border-color: color-mix(in srgb, var(--sg-accent) 18%, var(--sg-border-subtle));
  border-radius: var(--sg-radius-md);
}

.sg-pin-look-outline .sg-pin-cell {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-subtle));
}

.sg-pin-look-glass .sg-pin-cell {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, var(--sg-border-subtle));
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 45%, transparent);
  backdrop-filter: blur(8px);
}

/* —— NavLink —— */
.sg-nav-link {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.4rem 0.65rem;
  border-radius: var(--sg-radius-sm);
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  text-decoration: none;
  line-height: 1.2;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-nav-link:hover {
  color: var(--sg-fg);
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, transparent);
}

.sg-nav-link:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-nav-link-active,
.sg-nav-link[data-active="true"] {
  color: var(--sg-fg);
  background: var(--sg-accent-soft);
}

.sg-nav-link-look-solid.sg-nav-link-active,
.sg-nav-link-look-solid[data-active="true"] {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-nav-link-look-underline {
  border-radius: 0;
  padding-inline: 0.15rem;
  background: transparent;
  box-shadow: inset 0 -2px 0 transparent;
}

.sg-nav-link-look-underline:hover {
  background: transparent;
  color: var(--sg-fg);
}

.sg-nav-link-look-underline.sg-nav-link-active,
.sg-nav-link-look-underline[data-active="true"] {
  background: transparent;
  color: var(--sg-accent);
  box-shadow: inset 0 -2px 0 var(--sg-accent);
}

.sg-nav-link-look-pill {
  border-radius: var(--sg-radius-pill);
}

.sg-nav-link-look-pill.sg-nav-link-active,
.sg-nav-link-look-pill[data-active="true"] {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-nav-link-leading {
  display: inline-flex;
  flex-shrink: 0;
}

/* —— ListItem —— */
.sg-list-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  padding: 0.75rem 0.9rem;
  border-radius: var(--sg-radius-md);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 12%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-fg-muted) 5%, var(--sg-surface-solid));
  color: var(--sg-fg);
  box-sizing: border-box;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-list-item-interactive {
  cursor: pointer;
}

.sg-list-item-interactive:hover {
  background: color-mix(in srgb, var(--sg-accent) 8%, var(--sg-surface-solid));
}

.sg-list-item-interactive:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-list-item-selected,
.sg-list-item[data-selected="true"] {
  border-color: color-mix(in srgb, var(--sg-accent) 40%, transparent);
  background: var(--sg-accent-soft);
}

.sg-list-item-disabled,
.sg-list-item[data-disabled="true"] {
  opacity: 0.5;
  pointer-events: none;
}

.sg-list-item-leading {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.sg-list-item-body {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 0.15rem;
}

.sg-list-item-title {
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  line-height: 1.3;
}

.sg-list-item-description {
  font-size: var(--sg-text-xs);
  color: var(--sg-fg-muted);
  line-height: 1.35;
}

.sg-list-item-trailing {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-xs);
}

.sg-list-item-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-list-item-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 30%, var(--sg-border-subtle));
}

.sg-list-item-look-ghost {
  background: transparent;
  border-color: transparent;
  padding-inline: 0.25rem;
}

/* —— CopyButton —— */
.sg-copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  margin: 0;
  padding: 0.45rem 0.85rem;
  border-radius: var(--sg-radius-pill);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-subtle));
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  line-height: 1;
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-copy-btn:hover:not(:disabled) {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
}

.sg-copy-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-copy-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sg-copy-btn-sm {
  padding: 0.3rem 0.65rem;
  font-size: var(--sg-text-xs);
}

.sg-copy-btn-lg {
  padding: 0.55rem 1.1rem;
  font-size: var(--sg-text-base);
}

.sg-copy-btn-copied,
.sg-copy-btn[data-copied="true"] {
  background: color-mix(in srgb, var(--sg-success) 16%, var(--sg-surface-solid));
  border-color: color-mix(in srgb, var(--sg-success) 35%, transparent);
  color: var(--sg-success);
}

.sg-copy-btn-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  color: var(--sg-fg);
}

.sg-copy-btn-look-solid:hover:not(:disabled) {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-copy-btn-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-subtle));
  color: var(--sg-accent);
}

.sg-copy-btn-look-outline:hover:not(:disabled) {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
}

.sg-copy-btn-look-ghost {
  background: transparent;
  border-color: transparent;
  color: var(--sg-fg-muted);
  text-decoration: underline;
  text-underline-offset: 0.12em;
}

.sg-copy-btn-look-ghost:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, transparent);
  color: var(--sg-fg);
  text-decoration: none;
}

/* —— CharacterCount —— */
.sg-char-count {
  margin: 0;
  font-size: var(--sg-text-xs);
  font-variant-numeric: tabular-nums;
  color: var(--sg-fg-muted);
  line-height: 1.3;
}

.sg-char-count-look-soft {
  color: var(--sg-fg);
}

.sg-char-count-look-solid {
  display: inline-flex;
  padding: 0.1rem 0.4rem;
  border-radius: var(--sg-radius-xs);
  background: var(--sg-surface-solid);
  border: 1px solid var(--sg-border-subtle);
  color: var(--sg-fg);
}

.sg-char-count-look-muted {
  color: var(--sg-fg-muted);
}

.sg-char-count-look-danger,
.sg-char-count-over,
.sg-char-count[data-over="true"] {
  color: var(--sg-danger);
  font-weight: var(--sg-font-weight-medium);
}

/* —— Fieldset —— */
.sg-fieldset {
  margin: 0;
  padding: 1rem 1.1rem 1.1rem;
  border-radius: var(--sg-radius-md);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 14%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-fg-muted) 4%, var(--sg-surface-solid));
  min-width: 0;
}

.sg-fieldset-legend {
  padding: 0 0.4rem;
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  color: var(--sg-fg);
}

.sg-fieldset-body {
  display: grid;
  gap: var(--sg-space-3);
}

.sg-fieldset-compact {
  padding: 0.65rem 0.75rem 0.75rem;
}

.sg-fieldset-compact .sg-fieldset-body {
  gap: var(--sg-space-2);
}

.sg-fieldset-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-fieldset-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 30%, var(--sg-border-subtle));
}

.sg-fieldset-look-ghost {
  background: transparent;
  border-color: transparent;
  padding-inline: 0;
}

/* —— Icon —— */
.sg-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  border-radius: var(--sg-radius-sm);
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  font-size: 1rem;
  line-height: 1;
  vertical-align: middle;
}

.sg-icon > svg {
  width: 1.1em;
  height: 1.1em;
  display: block;
}

.sg-icon-sm {
  width: 1.5rem;
  height: 1.5rem;
  font-size: 0.85rem;
}

.sg-icon-lg {
  width: 2.5rem;
  height: 2.5rem;
  font-size: 1.25rem;
}

.sg-icon-xl {
  width: 3rem;
  height: 3rem;
  font-size: 1.5rem;
}

.sg-icon-look-solid {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-icon-look-outline {
  background: transparent;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 40%, transparent);
  color: var(--sg-accent);
}

.sg-icon-look-ghost {
  background: transparent;
  color: var(--sg-fg-muted);
}

/* —— Image —— */
.sg-image {
  position: relative;
  display: block;
  overflow: hidden;
  width: 100%;
  background: color-mix(in srgb, var(--sg-fg-muted) 8%, var(--sg-surface-solid));
  border: 1px solid color-mix(in srgb, var(--sg-fg-muted) 12%, transparent);
  border-radius: var(--sg-radius-md);
}

.sg-image-media {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sg-image-fit-cover .sg-image-media {
  object-fit: cover;
}

.sg-image-fit-contain .sg-image-media {
  object-fit: contain;
}

.sg-image-fit-fill .sg-image-media {
  object-fit: fill;
}

.sg-image-fit-none .sg-image-media {
  object-fit: none;
}

.sg-image-rounded-none {
  border-radius: 0;
}

.sg-image-rounded-sm {
  border-radius: var(--sg-radius-sm);
}

.sg-image-rounded-lg {
  border-radius: var(--sg-radius-lg);
}

.sg-image-rounded-full {
  border-radius: 999px;
}

.sg-image-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  min-height: 4rem;
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: 0.04em;
}

.sg-image-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-image-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 30%, var(--sg-border-subtle));
}

.sg-image-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, transparent);
  backdrop-filter: blur(8px);
}

/* —— Meter —— */
.sg-meter {
  display: grid;
  gap: 0.35rem;
  width: 100%;
  color: var(--sg-accent);
}

.sg-meter-header {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: var(--sg-text-sm);
}

.sg-meter-label {
  color: var(--sg-fg);
  font-weight: var(--sg-font-weight-medium);
}

.sg-meter-value {
  color: var(--sg-fg-muted);
  font-variant-numeric: tabular-nums;
}

.sg-meter-track {
  height: 0.5rem;
  overflow: hidden;
  border-radius: var(--sg-radius-pill);
  background: color-mix(in srgb, var(--sg-fg-muted) 14%, var(--sg-surface-solid));
}

.sg-meter-fill {
  height: 100%;
  border-radius: inherit;
  background: currentColor;
  transition: width 160ms ease;
}

.sg-meter-look-solid .sg-meter-track {
  background: var(--sg-surface-solid);
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
}

.sg-meter-look-glass .sg-meter-track {
  background: color-mix(in srgb, var(--sg-surface-solid) 55%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 45%, transparent);
}

.sg-meter-look-striped .sg-meter-fill {
  background-image:
    linear-gradient(
      45deg,
      color-mix(in srgb, #fff 18%, transparent) 25%,
      transparent 25%,
      transparent 50%,
      color-mix(in srgb, #fff 18%, transparent) 50%,
      color-mix(in srgb, #fff 18%, transparent) 75%,
      transparent 75%,
      transparent
    ),
    linear-gradient(90deg, currentColor, currentColor);
  background-size: 0.7rem 0.7rem, 100% 100%;
}

.sg-meter-success {
  color: var(--sg-success);
}

.sg-meter-warning {
  color: var(--sg-warning);
}

.sg-meter-danger {
  color: var(--sg-danger);
}

.sg-meter-muted {
  color: var(--sg-fg-muted);
}

/* —— TimeInput (custom Softglass HH:mm — not native OS picker) —— */
.sg-time {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.35rem 0.55rem 0.35rem 0.45rem;
  border-radius: var(--sg-radius-pill);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 20%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-surface-solid) 78%, var(--sg-accent-soft));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 55%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
  vertical-align: middle;
  user-select: none;
}

.sg-time-block {
  display: flex;
  width: 100%;
}

.sg-time[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

.sg-time[data-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 20%, transparent);
}

.sg-time-glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2.1rem;
  height: 2.1rem;
  border-radius: 50%;
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

.sg-time-glyph-face {
  position: relative;
  width: 1.05rem;
  height: 1.05rem;
  border-radius: 50%;
  border: 1.5px solid currentColor;
}

.sg-time-glyph-hand {
  position: absolute;
  left: 50%;
  bottom: 50%;
  width: 1.5px;
  background: currentColor;
  transform-origin: bottom center;
  border-radius: 1px;
}

.sg-time-glyph-hand-h {
  height: 0.28rem;
  transform: translateX(-50%) rotate(40deg);
}

.sg-time-glyph-hand-m {
  height: 0.38rem;
  transform: translateX(-50%) rotate(120deg);
  opacity: 0.85;
}

.sg-time-segments {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
}

.sg-time-segment {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 0.05rem;
}

.sg-time-step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 0.85rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--sg-fg-muted);
  font-size: 0.55rem;
  line-height: 1;
  cursor: pointer;
}

.sg-time-step:hover:not(:disabled) {
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
}

.sg-time-step:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.sg-time-value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.1rem;
  height: 1.85rem;
  margin: 0;
  padding: 0 0.25rem;
  border: 0;
  border-radius: var(--sg-radius-sm);
  background: var(--sg-surface-solid);
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: 1.05rem;
  font-weight: var(--sg-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  line-height: 1;
  cursor: default;
}

.sg-time-value:focus-visible {
  outline: none;
  box-shadow:
    inset 0 0 0 1px var(--sg-accent),
    0 0 0 3px var(--sg-ring-soft);
}

.sg-time-colon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 0.65rem;
  padding-bottom: 0.15rem;
  color: var(--sg-accent);
  font-size: 1.15rem;
  font-weight: var(--sg-font-weight-semibold);
  line-height: 1;
  opacity: 0.85;
  animation: sg-time-colon-blink 1.4s steps(1) infinite;
}

@keyframes sg-time-colon-blink {
  0%,
  50% {
    opacity: 0.9;
  }
  51%,
  100% {
    opacity: 0.25;
  }
}

.sg-time-ampm {
  display: inline-flex;
  flex-direction: column;
  gap: 0.15rem;
  margin-left: 0.25rem;
}

.sg-time-ampm-btn {
  margin: 0;
  padding: 0.15rem 0.4rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--sg-fg-muted);
  font-size: 0.65rem;
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: 0.04em;
  line-height: 1.2;
  cursor: pointer;
}

.sg-time-ampm-btn:hover:not(:disabled) {
  color: var(--sg-fg);
  background: color-mix(in srgb, var(--sg-fg-muted) 10%, transparent);
}

.sg-time-ampm-active {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
}

.sg-time-sm .sg-time-glyph {
  width: 1.75rem;
  height: 1.75rem;
}

.sg-time-sm .sg-time-value {
  min-width: 1.75rem;
  height: 1.55rem;
  font-size: 0.9rem;
}

.sg-time-lg .sg-time-glyph {
  width: 2.45rem;
  height: 2.45rem;
}

.sg-time-lg .sg-time-value {
  min-width: 2.45rem;
  height: 2.15rem;
  font-size: 1.25rem;
}

/* Looks */
.sg-time-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  border-radius: var(--sg-radius-md);
  box-shadow: none;
}

.sg-time-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-subtle));
  box-shadow: none;
}

.sg-time-look-outline .sg-time-value {
  background: transparent;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 28%, transparent);
}

.sg-time-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 48%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, var(--sg-border-subtle));
  backdrop-filter: blur(10px);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
}

/* —— ScrollArea —— */
.sg-scroll-area {
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0.5rem;
  border-radius: var(--sg-radius-md);
  border: 1px solid color-mix(in srgb, var(--sg-fg-muted) 14%, transparent);
  background: color-mix(in srgb, var(--sg-fg-muted) 4%, var(--sg-surface-solid));
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--sg-fg-muted) 35%, transparent) transparent;
}

.sg-scroll-area-x {
  overflow-x: auto;
  overflow-y: hidden;
}

.sg-scroll-area-both {
  overflow: auto;
}

.sg-scroll-area-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-scroll-area-look-ghost {
  background: transparent;
  border-color: transparent;
  padding-inline: 0;
}

/* —— Rating (Softglass SVG stars in a soft shell) —— */
.sg-rating {
  --sg-rating-on: #f5b942;
  --sg-rating-on-soft: color-mix(in srgb, #f5b942 28%, transparent);
  --sg-rating-off: color-mix(in srgb, var(--sg-fg-muted) 28%, var(--sg-surface-solid));
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.4rem 0.65rem;
  border-radius: var(--sg-radius-pill);
  border: 1px solid color-mix(in srgb, var(--sg-warning) 22%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-surface-solid) 82%, #f5b942);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 55%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
  vertical-align: middle;
  user-select: none;
}

.sg-rating-color-accent {
  --sg-rating-on: var(--sg-accent);
  --sg-rating-on-soft: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-surface-solid) 82%, var(--sg-accent-soft));
}

.sg-rating-color-rose {
  --sg-rating-on: #f472b6;
  --sg-rating-on-soft: color-mix(in srgb, #f472b6 26%, transparent);
  border-color: color-mix(in srgb, #f472b6 28%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-surface-solid) 82%, #f472b6);
}

.sg-rating-caption {
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-semibold);
  color: var(--sg-fg-muted);
  letter-spacing: 0.02em;
  padding-inline: 0.15rem 0.25rem;
  white-space: nowrap;
}

.sg-rating-stars {
  display: inline-flex;
  align-items: center;
  gap: 0.1rem;
}

.sg-rating-star {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.85rem;
  height: 1.85rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--sg-rating-on);
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  transition:
    transform var(--sg-duration-fast) var(--sg-ease-out),
    background var(--sg-duration-fast) var(--sg-ease-out),
    box-shadow var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-rating-svg {
  display: block;
  overflow: visible;
}

.sg-rating-svg-path {
  transition:
    fill var(--sg-duration-fast) var(--sg-ease-out),
    stroke var(--sg-duration-fast) var(--sg-ease-out),
    filter var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-rating-svg-path-off {
  fill: var(--sg-rating-off);
  stroke: color-mix(in srgb, var(--sg-fg-muted) 35%, transparent);
  stroke-width: 1;
}

.sg-rating-svg-path-on {
  fill: var(--sg-rating-on);
  stroke: color-mix(in srgb, var(--sg-rating-on) 55%, #000);
  stroke-width: 0.6;
  filter: drop-shadow(0 1px 2px color-mix(in srgb, var(--sg-rating-on) 45%, transparent));
}

.sg-rating-star-active {
  background: color-mix(in srgb, var(--sg-rating-on) 14%, transparent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--sg-rating-on) 18%, transparent);
}

.sg-rating-star:hover:not(:disabled) {
  transform: translateY(-1px) scale(1.08);
  background: var(--sg-rating-on-soft);
}

.sg-rating-star:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-rating-star:disabled {
  cursor: default;
}

.sg-rating-score {
  min-width: 2rem;
  padding: 0.2rem 0.45rem;
  border-radius: 999px;
  background: var(--sg-surface-solid);
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
  color: var(--sg-fg);
  font-size: var(--sg-text-xs);
  font-weight: var(--sg-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  text-align: center;
  line-height: 1.2;
}

.sg-rating-sm {
  padding: 0.28rem 0.5rem;
  gap: 0.4rem;
}

.sg-rating-sm .sg-rating-star {
  width: 1.45rem;
  height: 1.45rem;
  font-size: 0.95rem;
}

.sg-rating-lg {
  padding: 0.5rem 0.8rem;
  gap: 0.65rem;
}

.sg-rating-lg .sg-rating-star {
  width: 2.25rem;
  height: 2.25rem;
  font-size: 1.45rem;
}

.sg-rating-lg .sg-rating-score {
  min-width: 2.4rem;
  font-size: var(--sg-text-sm);
  padding: 0.3rem 0.55rem;
}

/* Looks */
.sg-rating-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  border-radius: var(--sg-radius-md);
  box-shadow: none;
}

.sg-rating-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-rating-on) 40%, var(--sg-border-subtle));
  box-shadow: none;
}

.sg-rating-look-outline .sg-rating-svg-path-off {
  fill: transparent;
  stroke: color-mix(in srgb, var(--sg-fg-muted) 45%, transparent);
  stroke-width: 1.4;
}

.sg-rating-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 48%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, var(--sg-border-subtle));
  backdrop-filter: blur(10px);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
}

.sg-rating-look-glow {
  border-color: color-mix(in srgb, var(--sg-rating-on) 40%, transparent);
  box-shadow:
    0 0 0 3px color-mix(in srgb, var(--sg-rating-on) 16%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent);
}

.sg-rating-look-glow .sg-rating-star-active .sg-rating-svg-path-on {
  filter: drop-shadow(0 0 6px color-mix(in srgb, var(--sg-rating-on) 65%, transparent));
}

.sg-rating-static .sg-rating-star:hover {
  transform: none;
  background: transparent;
}

.sg-rating-static .sg-rating-star-active:hover {
  background: color-mix(in srgb, var(--sg-rating-on) 14%, transparent);
}

.sg-rating[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

/* —— AspectRatio —— */
.sg-aspect-ratio {
  position: relative;
  width: 100%;
  overflow: hidden;
}

.sg-aspect-ratio-content {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.sg-aspect-ratio-content > * {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

@media (prefers-reduced-motion: reduce) {
  .sg-spinner-visual,
  .sg-skeleton,
  .sg-progress-indeterminate .sg-progress-fill,
  .sg-progress-look-striped .sg-progress-fill,
  .sg-status-dot-pulse::before,
  .sg-circular-progress-indeterminate .sg-circular-progress-svg {
    animation: none;
  }

  .sg-progress-fill,
  .sg-circular-progress-fill,
  .sg-meter-fill,
  .sg-rating-star,
  .sg-time-colon {
    transition: none;
    animation: none;
  }

  .sg-rating-star:hover:not(:disabled) {
    transform: none;
  }
}

/* —— RangeSlider (dual thumb on Slider track language) —— */
.sg-range-slider {
  position: relative;
  height: var(--sg-touch-min);
  display: flex;
  align-items: center;
}

.sg-range-slider-track {
  position: absolute;
  left: 0;
  right: 0;
  height: 0.45rem;
  border-radius: var(--sg-radius-pill);
  background: color-mix(in srgb, var(--sg-fg-muted) 14%, var(--sg-surface-solid));
  pointer-events: none;
}

.sg-range-slider-track::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--sg-range-left, 0%);
  width: calc(var(--sg-range-right, 100%) - var(--sg-range-left, 0%));
  border-radius: inherit;
  background: var(--sg-accent);
}

.sg-range-slider-input {
  position: absolute;
  left: 0;
  width: 100%;
  margin: 0;
  background: transparent !important;
  pointer-events: none;
}

.sg-range-slider-input::-webkit-slider-thumb {
  pointer-events: auto;
  position: relative;
  z-index: 2;
}

.sg-range-slider-input::-moz-range-thumb {
  pointer-events: auto;
  position: relative;
  z-index: 2;
}

.sg-range-slider-max {
  z-index: 3;
}

/* —— ToggleGroup —— */
.sg-toggle-group {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  vertical-align: middle;
}

.sg-toggle-group-block {
  display: flex;
}

.sg-toggle-group-block .sg-toggle-group-item {
  flex: 1;
}

.sg-toggle-group-item {
  margin: 0;
  padding: 0.45rem 0.85rem;
  border-radius: var(--sg-radius-pill);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 18%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-fg-muted) 6%, var(--sg-surface-solid));
  color: var(--sg-fg-muted);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  line-height: 1.2;
  cursor: pointer;
  transition:
    background var(--sg-duration-fast) var(--sg-ease-out),
    color var(--sg-duration-fast) var(--sg-ease-out),
    border-color var(--sg-duration-fast) var(--sg-ease-out);
}

.sg-toggle-group-item:hover:not(:disabled):not(.sg-toggle-group-item-on) {
  color: var(--sg-fg);
  border-color: color-mix(in srgb, var(--sg-accent) 30%, var(--sg-border-subtle));
}

.sg-toggle-group-item-on {
  background: var(--sg-accent);
  border-color: transparent;
  color: var(--sg-accent-fg);
}

.sg-toggle-group-item:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-toggle-group-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.sg-toggle-group-sm .sg-toggle-group-item {
  padding: 0.3rem 0.65rem;
  font-size: var(--sg-text-xs);
}

.sg-toggle-group-lg .sg-toggle-group-item {
  padding: 0.55rem 1.05rem;
  font-size: var(--sg-text-base);
}

.sg-toggle-group-look-solid .sg-toggle-group-item {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-toggle-group-look-outline .sg-toggle-group-item {
  background: transparent;
}

.sg-toggle-group-look-outline .sg-toggle-group-item-on {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
  border-color: var(--sg-accent);
}

.sg-toggle-group-look-glass .sg-toggle-group-item {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  backdrop-filter: blur(8px);
}

/* —— CountBadge —— */
.sg-count-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 0.35rem;
  border-radius: 999px;
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 25%, transparent);
  font-size: 0.7rem;
  font-weight: var(--sg-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  vertical-align: middle;
}

.sg-count-badge-sm {
  min-width: 1rem;
  height: 1rem;
  font-size: 0.6rem;
  padding: 0 0.25rem;
}

.sg-count-badge-lg {
  min-width: 1.5rem;
  height: 1.5rem;
  font-size: 0.8rem;
  padding: 0 0.45rem;
}

.sg-count-badge-look-solid {
  background: var(--sg-accent);
  color: var(--sg-accent-fg);
  border-color: transparent;
}

.sg-count-badge-look-outline {
  background: transparent;
  color: var(--sg-accent);
}

.sg-count-badge-look-danger {
  background: color-mix(in srgb, var(--sg-danger) 14%, transparent);
  color: var(--sg-danger);
  border-color: color-mix(in srgb, var(--sg-danger) 30%, transparent);
}

/* —— ColorSwatch / ColorInput —— */
.sg-swatch {
  --sg-swatch-color: #7c3aed;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  margin: 0;
  padding: 0.2rem;
  border-radius: 50%;
  border: 1px solid color-mix(in srgb, var(--sg-fg) 12%, transparent);
  background: var(--sg-surface-solid);
  cursor: pointer;
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 40%, transparent);
}

.sg-swatch-fill {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--sg-swatch-color);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #000 12%, transparent);
}

.sg-swatch-sm {
  width: 1.5rem;
  height: 1.5rem;
}

.sg-swatch-lg {
  width: 2.5rem;
  height: 2.5rem;
}

.sg-swatch-selected {
  box-shadow:
    0 0 0 2px var(--sg-surface-solid),
    0 0 0 4px var(--sg-accent);
}

.sg-swatch:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--sg-ring-soft);
}

.sg-swatch-look-outline {
  background: transparent;
}

.sg-swatch-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  backdrop-filter: blur(6px);
}

.sg-color-input {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.3rem 0.45rem 0.3rem 0.35rem;
  border-radius: var(--sg-radius-pill);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 18%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-surface-solid) 85%, var(--sg-accent-soft));
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 45%, transparent);
}

.sg-color-input-swatch {
  position: relative;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
  border: 1px solid var(--sg-border-subtle);
  cursor: pointer;
}

.sg-color-input-native {
  position: absolute;
  inset: -20%;
  width: 140%;
  height: 140%;
  border: 0;
  padding: 0;
  cursor: pointer;
}

.sg-color-input-text {
  flex: 1;
  min-width: 0;
  margin: 0;
  padding: 0.35rem 0.4rem;
  border: 0;
  background: transparent;
  color: var(--sg-fg);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: var(--sg-text-sm);
  outline: none;
}

.sg-color-input-look-solid {
  background: var(--sg-surface-solid);
  border-radius: var(--sg-radius-md);
  box-shadow: none;
}

.sg-color-input-look-outline {
  background: transparent;
  box-shadow: none;
}

.sg-color-input-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  backdrop-filter: blur(8px);
}

.sg-color-input[data-invalid="true"] {
  border-color: var(--sg-danger);
}

/* —— Highlight / Truncate / LiveRegion —— */
.sg-highlight {
  padding: 0.05em 0.2em;
  border-radius: 0.25em;
  background: color-mix(in srgb, var(--sg-warning) 28%, transparent);
  color: inherit;
}

.sg-highlight-look-solid {
  background: var(--sg-warning);
  color: #1a1200;
}

.sg-highlight-look-accent {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
}

.sg-highlight-look-warning {
  background: color-mix(in srgb, var(--sg-warning) 40%, transparent);
}

.sg-truncate {
  display: inline-block;
  max-width: 100%;
  overflow: hidden;
}

.sg-truncate-1 {
  white-space: nowrap;
  text-overflow: ellipsis;
}

.sg-truncate-2,
.sg-truncate-3,
.sg-truncate-4 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.sg-truncate-2 {
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.sg-truncate-3 {
  -webkit-line-clamp: 3;
  line-clamp: 3;
}

.sg-truncate-4 {
  -webkit-line-clamp: 4;
  line-clamp: 4;
}

/* —— NativeDateInput (custom Softglass YYYY-MM-DD — not OS picker) —— */
.sg-ndate {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  padding: 0.4rem 0.6rem 0.4rem 0.45rem;
  border-radius: var(--sg-radius-pill);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 20%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-surface-solid) 78%, var(--sg-accent-soft));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 55%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
  vertical-align: middle;
  user-select: none;
}

.sg-ndate-block {
  display: flex;
  width: 100%;
}

.sg-ndate[data-disabled="true"] {
  opacity: 0.55;
  pointer-events: none;
}

.sg-ndate[data-invalid="true"] {
  border-color: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 20%, transparent);
}

.sg-ndate-glyph {
  display: inline-flex;
  flex-direction: column;
  align-items: stretch;
  width: 2rem;
  height: 2rem;
  border-radius: 0.45rem;
  overflow: hidden;
  flex-shrink: 0;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 25%, transparent);
  background: var(--sg-surface-solid);
}

.sg-ndate-glyph-top {
  height: 0.45rem;
  background: var(--sg-accent);
}

.sg-ndate-glyph-body {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.12rem;
  padding: 0.22rem;
  background: color-mix(in srgb, var(--sg-accent-soft) 55%, var(--sg-surface-solid));
}

.sg-ndate-glyph-dot {
  border-radius: 2px;
  background: color-mix(in srgb, var(--sg-accent) 45%, transparent);
}

.sg-ndate-segments {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
}

.sg-ndate-segment {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 0.05rem;
}

.sg-ndate-step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.7rem;
  height: 0.85rem;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--sg-fg-muted);
  font-size: 0.55rem;
  line-height: 1;
  cursor: pointer;
}

.sg-ndate-step:hover:not(:disabled) {
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
}

.sg-ndate-value {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2rem;
  height: 1.85rem;
  margin: 0;
  padding: 0 0.35rem;
  border: 0;
  border-radius: var(--sg-radius-sm);
  background: var(--sg-surface-solid);
  box-shadow: inset 0 0 0 1px var(--sg-border-subtle);
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: 0.95rem;
  font-weight: var(--sg-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  cursor: default;
}

.sg-ndate-value-month {
  min-width: 2.6rem;
  letter-spacing: 0.02em;
}

.sg-ndate-value-year {
  min-width: 3rem;
}

.sg-ndate-value:focus-visible {
  outline: none;
  box-shadow:
    inset 0 0 0 1px var(--sg-accent),
    0 0 0 3px var(--sg-ring-soft);
}

.sg-ndate-sep {
  color: var(--sg-fg-muted);
  font-weight: var(--sg-font-weight-semibold);
  opacity: 0.55;
  padding-bottom: 0.1rem;
}

.sg-ndate-sm .sg-ndate-glyph {
  width: 1.7rem;
  height: 1.7rem;
}

.sg-ndate-sm .sg-ndate-value {
  height: 1.55rem;
  font-size: 0.82rem;
  min-width: 1.7rem;
}

.sg-ndate-lg .sg-ndate-glyph {
  width: 2.35rem;
  height: 2.35rem;
}

.sg-ndate-lg .sg-ndate-value {
  height: 2.15rem;
  font-size: 1.1rem;
  min-width: 2.35rem;
}

.sg-ndate-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  border-radius: var(--sg-radius-md);
  box-shadow: none;
}

.sg-ndate-look-outline {
  background: transparent;
  border-color: color-mix(in srgb, var(--sg-accent) 40%, var(--sg-border-subtle));
  box-shadow: none;
}

.sg-ndate-look-outline .sg-ndate-value {
  background: transparent;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--sg-accent) 28%, transparent);
}

.sg-ndate-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 48%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, var(--sg-border-subtle));
  backdrop-filter: blur(10px);
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 50%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 6%, transparent);
}

/* —— LiveRegion (visible Softglass status banner) —— */
.sg-live-region-visible {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  width: 100%;
  padding: 0.7rem 0.9rem;
  border-radius: var(--sg-radius-md);
  border: 1px solid color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-accent-soft) 70%, var(--sg-surface-solid));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, #fff 45%, transparent),
    0 1px 2px color-mix(in srgb, var(--sg-fg) 5%, transparent);
  color: var(--sg-fg);
  font-size: var(--sg-text-sm);
  line-height: 1.4;
}

.sg-live-region-marker {
  flex-shrink: 0;
  width: 0.5rem;
  height: 0.5rem;
  margin-top: 0.35rem;
  border-radius: 50%;
  background: var(--sg-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

.sg-live-region-body {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 0.15rem;
}

.sg-live-region-title {
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight, -0.01em);
}

.sg-live-region-message {
  color: var(--sg-fg-muted);
}

.sg-live-look-solid {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-live-look-glass {
  background: color-mix(in srgb, var(--sg-surface-solid) 50%, transparent);
  border-color: color-mix(in srgb, var(--sg-fg) 12%, transparent);
  backdrop-filter: blur(10px);
}

.sg-live-look-info {
  border-color: color-mix(in srgb, var(--sg-accent) 35%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-accent-soft) 80%, var(--sg-surface-solid));
}

.sg-live-look-info .sg-live-region-marker {
  background: var(--sg-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-accent) 22%, transparent);
}

.sg-live-look-success {
  border-color: color-mix(in srgb, var(--sg-success) 35%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-success) 12%, var(--sg-surface-solid));
}

.sg-live-look-success .sg-live-region-marker {
  background: var(--sg-success);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-success) 22%, transparent);
}

.sg-live-look-success .sg-live-region-message {
  color: var(--sg-fg);
}

.sg-live-look-warning {
  border-color: color-mix(in srgb, var(--sg-warning) 40%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-warning) 14%, var(--sg-surface-solid));
}

.sg-live-look-warning .sg-live-region-marker {
  background: var(--sg-warning);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-warning) 22%, transparent);
}

.sg-live-look-danger {
  border-color: color-mix(in srgb, var(--sg-danger) 40%, var(--sg-border-subtle));
  background: color-mix(in srgb, var(--sg-danger) 12%, var(--sg-surface-solid));
}

.sg-live-look-danger .sg-live-region-marker {
  background: var(--sg-danger);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--sg-danger) 22%, transparent);
}

/* —— Text / Heading —— */
.sg-text {
  margin: 0;
  color: var(--sg-fg);
  font-size: var(--sg-text-base);
  line-height: var(--sg-leading-normal, 1.5);
}

.sg-text-muted {
  color: var(--sg-fg-muted);
}

.sg-text-subtle {
  color: var(--sg-fg-subtle, var(--sg-fg-muted));
}

.sg-text-accent {
  color: var(--sg-accent);
}

.sg-text-danger {
  color: var(--sg-danger);
}

.sg-text-size-xs {
  font-size: var(--sg-text-xs);
}

.sg-text-size-sm {
  font-size: var(--sg-text-sm);
}

.sg-text-size-lg {
  font-size: var(--sg-text-lg);
}

.sg-text-size-xl {
  font-size: var(--sg-text-xl, 1.25rem);
}

.sg-text-weight-medium {
  font-weight: var(--sg-font-weight-medium);
}

.sg-text-weight-semibold {
  font-weight: var(--sg-font-weight-semibold);
}

.sg-text-weight-bold {
  font-weight: var(--sg-font-weight-bold, 700);
}

.sg-heading {
  margin: 0;
  color: var(--sg-fg);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight, -0.02em);
  line-height: 1.25;
}

.sg-heading-sm {
  font-size: var(--sg-text-base);
}

.sg-heading-lg {
  font-size: var(--sg-text-xl, 1.25rem);
}

.sg-heading-xl {
  font-size: 1.5rem;
}

.sg-heading-2xl {
  font-size: 1.85rem;
}

/* Chip variants (filter / check) */
.sg-chip-variant-filter {
  border-style: dashed;
}

.sg-chip-variant-check .sg-chip-check {
  font-size: 0.75em;
  font-weight: 700;
}

/* —— Collapsible (v1.4a) — cheap frost; glass blur only when look=glass —— */
.sg-collapsible {
  --sg-disclosure-pad-x: 1.05rem;
  --sg-disclosure-pad-y: 0.85rem;
  display: flex;
  flex-direction: column;
  width: 100%;
  border-radius: var(--sg-radius-lg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  overflow: clip;
  contain: layout style;
}

.sg-collapsible[data-look="solid"] {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-collapsible[data-look="glass"] {
  /* Frost-first (cheap). Blur only if transparency allowed. */
  background: var(--sg-surface-frost-strong, var(--sg-surface-frost));
  border-color: color-mix(in srgb, var(--sg-border-frost) 80%, var(--sg-accent) 12%);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

@media (prefers-reduced-transparency: no-preference) {
  .sg-collapsible[data-look="glass"] {
    background: color-mix(in srgb, var(--sg-surface-glass) 92%, transparent);
    backdrop-filter: blur(12px) saturate(var(--sg-glass-saturate));
    -webkit-backdrop-filter: blur(12px) saturate(var(--sg-glass-saturate));
  }
}

.sg-collapsible[data-look="outline"] {
  background: transparent;
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-collapsible[data-look="ghost"] {
  background: transparent;
  border-color: transparent;
  border-radius: var(--sg-radius-md);
  box-shadow: none;
}

.sg-collapsible-trigger {
  appearance: none;
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  margin: 0;
  padding: var(--sg-disclosure-pad-y) var(--sg-disclosure-pad-x);
  border: 0;
  background: transparent;
  color: var(--sg-fg);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  text-align: left;
  cursor: pointer;
}

.sg-collapsible-trigger::before {
  content: "";
  position: absolute;
  left: 0.45rem;
  top: 50%;
  width: 3px;
  height: 0;
  border-radius: 999px;
  background: var(--sg-accent);
  transform: translateY(-50%);
  opacity: 0;
}

.sg-collapsible-trigger[data-state="open"]::before {
  height: 1.15rem;
  opacity: 1;
}

.sg-collapsible[data-look="ghost"] .sg-collapsible-trigger::before {
  left: 0;
}

.sg-collapsible-trigger:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-accent-soft) 70%, transparent);
}

.sg-collapsible-trigger[data-state="open"] {
  background: color-mix(in srgb, var(--sg-accent-soft) 55%, transparent);
}

.sg-collapsible-trigger:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: -2px;
  z-index: 1;
}

.sg-collapsible-trigger:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sg-collapsible-trigger-label {
  flex: 1;
  min-width: 0;
  padding-left: 0.35rem;
}

.sg-collapsible-chevron-wrap {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 999px;
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: color-mix(in srgb, var(--sg-surface-solid) 70%, var(--sg-accent-soft));
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  color: var(--sg-fg-muted);
}

.sg-collapsible-trigger:hover:not(:disabled) .sg-collapsible-chevron-wrap {
  border-color: color-mix(in srgb, var(--sg-accent) 28%, var(--sg-border-frost));
  color: var(--sg-accent);
}

.sg-collapsible-chevron-wrap[data-open="true"] {
  transform: rotate(180deg);
  color: var(--sg-accent-fg);
  background: var(--sg-accent);
  border-color: transparent;
}

.sg-collapsible-chevron {
  width: 0.95rem;
  height: 0.95rem;
  display: block;
}

.sg-collapsible-panel[hidden] {
  display: none;
}

.sg-collapsible-content {
  padding: 0.7rem var(--sg-disclosure-pad-x) 1.05rem;
  padding-left: calc(var(--sg-disclosure-pad-x) + 0.35rem);
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  line-height: 1.6;
  border-top: var(--sg-border-width) solid
    color-mix(in srgb, var(--sg-border-frost) 85%, transparent);
}

.sg-collapsible[data-look="ghost"] .sg-collapsible-content {
  border-top-color: transparent;
}

/* Fade only when requested — no layout animation */
.sg-collapsible[data-motion="fade"] .sg-collapsible-panel[data-state="open"] .sg-collapsible-content {
  animation: sg-disclosure-fade var(--sg-duration-fast) var(--sg-ease-out);
}

@keyframes sg-disclosure-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* —— Accordion (v1.4a) —— */
.sg-accordion {
  --sg-disclosure-pad-x: 1.05rem;
  --sg-disclosure-pad-y: 0.9rem;
  display: flex;
  flex-direction: column;
  width: 100%;
  border-radius: var(--sg-radius-lg);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  overflow: clip;
  contain: layout style;
}

.sg-accordion[data-look="solid"] {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-accordion[data-look="glass"] {
  background: var(--sg-surface-frost-strong, var(--sg-surface-frost));
  border-color: color-mix(in srgb, var(--sg-border-frost) 80%, var(--sg-accent) 12%);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

@media (prefers-reduced-transparency: no-preference) {
  .sg-accordion[data-look="glass"] {
    background: color-mix(in srgb, var(--sg-surface-glass) 92%, transparent);
    backdrop-filter: blur(12px) saturate(var(--sg-glass-saturate));
    -webkit-backdrop-filter: blur(12px) saturate(var(--sg-glass-saturate));
  }
}

.sg-accordion[data-look="outline"] {
  background: transparent;
  border-color: var(--sg-border-subtle);
  box-shadow: none;
}

.sg-accordion[data-look="ghost"] {
  background: transparent;
  border-color: transparent;
  border-radius: 0;
  box-shadow: none;
}

.sg-accordion-item {
  contain: layout style;
}

.sg-accordion-item + .sg-accordion-item {
  border-top: var(--sg-border-width) solid
    color-mix(in srgb, var(--sg-border-frost) 90%, transparent);
}

.sg-accordion[data-look="ghost"] .sg-accordion-item + .sg-accordion-item {
  border-top-color: var(--sg-border-subtle);
}

.sg-accordion-heading {
  margin: 0;
  font-size: inherit;
  font-weight: inherit;
}

.sg-accordion-trigger {
  appearance: none;
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--sg-space-3);
  margin: 0;
  padding: var(--sg-disclosure-pad-y) var(--sg-disclosure-pad-x);
