}

.sg-accordion[data-look="ghost"] .sg-accordion-trigger::before {
  left: 0;
}

.sg-accordion-trigger:hover:not(:disabled) {
  background: color-mix(in srgb, var(--sg-accent-soft) 70%, transparent);
}

.sg-accordion-trigger[data-state="open"] {
  background: color-mix(in srgb, var(--sg-accent-soft) 55%, transparent);
}

.sg-accordion-trigger:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: -2px;
  z-index: 1;
}

.sg-accordion-trigger:disabled {
