}

.sg-accordion-chevron-wrap {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 999px;
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: color-mix(in srgb, var(--sg-surface-solid) 70%, var(--sg-accent-soft));
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
  color: var(--sg-fg-muted);
}

.sg-accordion-trigger:hover:not(:disabled) .sg-accordion-chevron-wrap {
  border-color: color-mix(in srgb, var(--sg-accent) 28%, var(--sg-border-frost));
  color: var(--sg-accent);
}

.sg-accordion-chevron-wrap[data-open="true"] {
