}

.sg-accordion-panel[hidden] {
  display: none;
}

.sg-accordion-content {
  padding: 0 var(--sg-disclosure-pad-x) 1.05rem;
  padding-left: calc(var(--sg-disclosure-pad-x) + 0.35rem);
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  line-height: 1.6;
}

.sg-accordion[data-motion="fade"] .sg-accordion-panel[data-state="open"] .sg-accordion-content {
  animation: sg-disclosure-fade var(--sg-duration-fast) var(--sg-ease-out);
}

/* —— Breadcrumb (v1.4a) —— */
.sg-breadcrumb {
  min-width: 0;
  width: fit-content;
  max-width: 100%;
}

.sg-breadcrumb-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2rem 0.15rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sg-breadcrumb[data-look="soft"] {
  padding: 0.35rem 0.55rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-breadcrumb[data-look="pill"] .sg-breadcrumb-list {
  gap: 0.35rem;
}

.sg-breadcrumb-item {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
  font-size: var(--sg-text-sm);
  line-height: 1.4;
}

.sg-breadcrumb[data-size="sm"] .sg-breadcrumb-item {
  font-size: var(--sg-text-xs);
}

.sg-breadcrumb-separator {
  color: var(--sg-fg-subtle, var(--sg-fg-muted));
  opacity: 0.7;
  user-select: none;
  font-weight: var(--sg-font-weight-medium);
}

.sg-breadcrumb-link.sg-link {
  font-size: inherit;
  font-weight: var(--sg-font-weight-medium);
  text-decoration: none;
  border-radius: var(--sg-radius-sm);
  padding: 0.15rem 0.3rem;
  margin: -0.15rem -0.15rem;
}

.sg-breadcrumb-link.sg-link:hover {
  background: var(--sg-accent-soft);
  color: var(--sg-fg);
}

.sg-breadcrumb-page {
  color: var(--sg-fg);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  padding: 0.15rem 0.3rem;
}

.sg-breadcrumb[data-look="pill"] .sg-breadcrumb-separator {
  opacity: 0.45;
  font-size: 0.85em;
}

.sg-breadcrumb[data-look="pill"] .sg-breadcrumb-link.sg-link,
.sg-breadcrumb[data-look="pill"] .sg-breadcrumb-page {
  display: inline-flex;
  align-items: center;
  min-height: 1.7rem;
  padding: 0.2rem 0.7rem;
  margin: 0;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-breadcrumb[data-look="pill"] .sg-breadcrumb-link.sg-link:hover {
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 22%, var(--sg-border-frost));
}

.sg-breadcrumb[data-look="pill"] .sg-breadcrumb-page {
  color: var(--sg-accent-fg);
  background: var(--sg-accent);
  border-color: transparent;
}

/* —— Pagination (v1.4a) —— */
.sg-pagination {
  width: fit-content;
  max-width: 100%;
  contain: layout style;
}

.sg-pagination-list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.sg-pagination[data-look="soft"] .sg-pagination-list,
.sg-pagination[data-look="glass"] .sg-pagination-list {
  gap: 0.2rem;
  padding: 0.3rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid var(--sg-border-frost);
  background: var(--sg-surface-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-pagination[data-look="glass"] .sg-pagination-list {
  background: var(--sg-surface-frost-strong, var(--sg-surface-frost));
  border-color: color-mix(in srgb, var(--sg-border-frost) 75%, var(--sg-accent) 14%);
}

@media (prefers-reduced-transparency: no-preference) {
  .sg-pagination[data-look="glass"] .sg-pagination-list {
    background: color-mix(in srgb, var(--sg-surface-glass) 88%, transparent);
    backdrop-filter: blur(10px) saturate(var(--sg-glass-saturate));
    -webkit-backdrop-filter: blur(10px) saturate(var(--sg-glass-saturate));
  }
}

.sg-pagination-item {
  display: inline-flex;
}

.sg-pagination-btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.35rem;
  min-height: 2.35rem;
  padding: 0 0.7rem;
  border-radius: var(--sg-radius-pill);
  border: var(--sg-border-width) solid transparent;
  background: transparent;
  color: var(--sg-fg-muted);
  font-family: var(--sg-font-sans);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  letter-spacing: var(--sg-tracking-tight);
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}

.sg-pagination[data-size="sm"] .sg-pagination-btn {
  min-width: 1.95rem;
  min-height: 1.95rem;
  padding: 0 0.5rem;
  font-size: var(--sg-text-xs);
}

.sg-pagination[data-look="solid"] .sg-pagination-btn {
  background: var(--sg-surface-solid);
  border-color: var(--sg-border-subtle);
}

.sg-pagination[data-look="ghost"] .sg-pagination-btn {
  background: transparent;
  border-color: transparent;
}

.sg-pagination-btn:hover:not(:disabled):not([data-active="true"]) {
  color: var(--sg-fg);
  background: var(--sg-accent-soft);
  border-color: color-mix(in srgb, var(--sg-accent) 16%, transparent);
}

.sg-pagination-btn:focus-visible {
  outline: 2px solid var(--sg-ring);
  outline-offset: 2px;
}

.sg-pagination-btn[data-active="true"] {
  color: var(--sg-accent-fg);
  background: var(--sg-accent);
  border-color: transparent;
  font-weight: var(--sg-font-weight-semibold);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-pagination-btn[data-active="true"]:hover:not(:disabled) {
  background: var(--sg-accent-hover);
  color: var(--sg-accent-fg);
}

.sg-pagination-btn:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.sg-pagination-prev,
.sg-pagination-next {
  min-width: auto;
  padding-inline: 0.9rem;
  font-weight: var(--sg-font-weight-semibold);
}

.sg-pagination-ellipsis {
  min-width: 1.4rem;
  justify-content: center;
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  user-select: none;
  opacity: 0.75;
}

.sg-pagination-status {
  display: inline-flex;
  align-items: center;
  min-height: 2.35rem;
  padding: 0 0.75rem;
  color: var(--sg-fg-muted);
  font-size: var(--sg-text-sm);
  font-weight: var(--sg-font-weight-medium);
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion: reduce) {
  .sg-collapsible[data-motion="fade"] .sg-collapsible-content,
  .sg-accordion[data-motion="fade"] .sg-accordion-content {
    animation: none !important;
  }

  .sg-collapsible-chevron-wrap[data-open="true"],
  .sg-accordion-chevron-wrap[data-open="true"] {
    transition: none;
  }
}

/* —— EmptyState (v1.4b) —— */
.sg-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.65rem;
  width: 100%;
  padding: 2rem 1.5rem;
  border-radius: var(--sg-radius-lg);
  border: var(--sg-border-width) solid var(--sg-border-subtle);
  background: var(--sg-surface-solid);
  box-sizing: border-box;
  contain: layout style;
}

.sg-empty-state[data-look="soft"] {
  background: var(--sg-surface-frost);
  border-color: var(--sg-border-frost);
  box-shadow: inset 0 1px 0 var(--sg-gloss-highlight);
}

.sg-empty-state[data-look="outline"] {
  background: transparent;
  border-style: dashed;
  border-color: var(--sg-border-subtle);
}

.sg-empty-state[data-size="sm"] {
  padding: 1.25rem 1rem;
  gap: 0.45rem;
}

.sg-empty-state[data-size="lg"] {
  padding: 2.75rem 2rem;
  gap: 0.85rem;
}

.sg-empty-state-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  border-radius: var(--sg-radius-md);
  background: var(--sg-accent-soft);
  color: var(--sg-accent);
  font-size: 1.35rem;
  margin-bottom: 0.25rem;
}

