  width: 2.35rem;
  height: 2.35rem;
  font-size: 1.1rem;
}

.sg-empty-state-title {
  margin: 0;
  max-width: 28ch;
  font-size: var(--sg-text-lg);
  font-weight: var(--sg-font-weight-semibold);
  letter-spacing: var(--sg-tracking-tight);
  color: var(--sg-fg);
  line-height: var(--sg-leading-tight);
}

.sg-empty-state[data-size="sm"] .sg-empty-state-title {
  font-size: var(--sg-text-md, var(--sg-text-base));
}

.sg-empty-state[data-size="lg"] .sg-empty-state-title {
  font-size: var(--sg-text-xl);
}

.sg-empty-state-description {
  margin: 0;
  max-width: 42ch;
  font-size: var(--sg-text-sm);
  color: var(--sg-fg-muted);
  line-height: 1.55;
}

.sg-empty-state-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  margin-top: 0.55rem;
}

/* —— Sheet (v1.4b) —— */
.sg-sheet-root {
  position: fixed;
  inset: 0;
  z-index: var(--sg-z-modal);
  isolation: isolate;
  box-sizing: border-box;
}

.sg-sheet-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  padding: 0;
  margin: 0;
  cursor: pointer;
  background: color-mix(in srgb, var(--sg-bg) 40%, rgba(15, 23, 42, 0.4));
  /* frost first — light blur only */
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
